insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-01', 'top-fgd-07', 'Texto para questões 01 e 02
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-01-a', 'q-pnd25-01', 'difundir conhecimentos socioculturais atuais com base na neutralidade que o processo de ensino e de aprendizagem requer.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-01-b', 'q-pnd25-01', 'apresentar abordagens de temas socioculturais atuais e sensíveis que possam alterar o processo de ensino e de aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-01-c', 'q-pnd25-01', 'divulgar os saberes socioculturais atuais e a historicidade humana para atender aos estudantes de regiões de difícil acesso.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-01-d', 'q-pnd25-01', 'abordar os contextos socioculturais atuais considerados relevantes e a historicidade que consolidou a existência humana.', true, 'O PNLD busca oferecer materiais que dialoguem com temas socioculturais contemporâneos relevantes e com a historicidade que constituiu a experiência humana, sem pretensão de neutralidade absoluta.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-02', 'top-fgd-07', 'Texto para questões 01 e 02
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-02-a', 'q-pnd25-02', '“Escolho um livro que apresente temáticas sociais essenciais com reflexões sobre o conteúdo da disciplina”.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-02-b', 'q-pnd25-02', '“Prefiro os livros com sistematização coerente dos objetos de conhecimento da disciplina e transposição didática adequada”.', true, 'A função referencial diz respeito ao livro como suporte privilegiado de conteúdos e conhecimentos da disciplina, relacionando-se à sistematização e à transposição didática dos saberes considerados relevantes.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-02-c', 'q-pnd25-02', '“Considero adequados os livros que expressam conceitos por meio de elementos variados, como imagens, palavras, mapas e gráficos”.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-02-d', 'q-pnd25-02', '“Levo em consideração livros que apresentem a norma culta da língua e valores sociais predominantes nos conteúdos apresentados”.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-03', 'top-fgd-06', 'Em O alienista, o protagonista da trama é Simão Bacamarte, médico que funda a clínica Casa Verde para pessoas com distúrbios mentais, na pequena cidade de Itaguaí. Simão começa a tratar as pessoas da cidade que apresentam sinais de loucura e passa a buscar, por meio de seus estudos, formas de estabelecer quais comportamentos da população podem ser considerados normais ou anormais, o que se torna uma obsessão. A história é relatada por um narrador-observador que, ironicamente, fundamenta sua narrativa no registro histórico das crônicas da vila de Itaguaí. Com temáticas distintas, porém universais, o estudante do Ensino Médio é convidado a acompanhar de perto as experiências de Simão Bacamarte e se depara com dilemas envolvendo ciência, ética, exclusão social, loucura, imortalidade, entre outros temas também ambientados no contexto da época retratada por Machado de Assis.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-03-a', 'q-pnd25-03', 'estimulem a emissão de laudos pela equipe psicopedagógica para subsidiar intervenções feitas pelos professores.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-03-b', 'q-pnd25-03', 'desenvolvam ações de escuta entre os estudantes para que eles relacionem os temas abordados com suas vivências.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-03-c', 'q-pnd25-03', 'favoreçam críticas à excessiva medicamentalização dos comportamentos incomuns para promover reflexões sobre ética profissional.', true, 'A obra é utilizada para problematizar a excessiva medicalização de comportamentos considerados incomuns, promovendo reflexões sobre ética profissional a partir da trajetória do personagem Simão Bacamarte.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-03-d', 'q-pnd25-03', 'abordem a ciência médica por um viés objetivo para definir quais padrões de comportamento são socialmente aceitos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-04', 'top-fgd-23', 'Ao realizar a matrícula em uma escola, uma estudante de 15 anos e seus pais solicitaram à secretaria acadêmica o uso de nome social, já que na certidão de nascimento consta uma identificação masculina. Eles queriam que o nome social fosse usado em sala de aula e em documentos internos da instituição, como chamada, boletins e carteirinha estudantil. No entanto, a direção, ao tomar ciência do caso, recusou o pedido, alegando que, sem a alteração no registro civil, seria impossível atender à solicitação.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-04-a', 'q-pnd25-04', 'permitir o uso do nome social de maneira informal, mantendo os registros escolares internos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-04-b', 'q-pnd25-04', 'convocar o conselho estudantil para deliberar sobre o caso, por se tratar de uma questão interna da escola.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-04-c', 'q-pnd25-04', 'acatar o pedido quando o nome social for oficialmente retificado no registro civil da estudante.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-04-d', 'q-pnd25-04', 'atender ao pedido mediante formalização da solicitação pelos responsáveis legais da estudante.', true, 'A Resolução MEC n. 1/2018 garante o uso do nome social nos registros escolares mediante solicitação formal dos responsáveis legais, independentemente de alteração no registro civil.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-05', 'top-fgd-22', 'Texto para questões 05 e 06
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-05-a', 'q-pnd25-05', 'palestras com rappers na escola; e listagem dos objetivos da COP30 no quadro.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-05-b', 'q-pnd25-05', 'leitura coletiva dos textos; e fichamento das ideias centrais e secundárias da letra da canção.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-05-c', 'q-pnd25-05', 'interpretação da letra da canção; e pesquisa sobre ações que contribuem com a preservação da natureza.', true, 'Essa opção articula a análise crítica do texto poético/musical com uma investigação ativa sobre soluções ambientais, promovendo discussão crítica dos dois textos apresentados.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-05-d', 'q-pnd25-05', 'registro dos Objetivos de Desenvolvimento Sustentável (ODS) no caderno; e consulta de termos técnicos em dicionários.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-06', 'top-fgd-05', 'Texto para questões 05 e 06
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-06-a', 'q-pnd25-06', '1. realizar um levantamento do entorno escolar, problematizando questões ambientais da comunidade; 2. utilizar conceitos escolares que ajudam a compreender o tema; 3. aplicar os conhecimentos aprendidos previamente, considerando uma análise crítica das ideias debatidas na COP30 e no rap Chuva Ácida.', true, 'A sequência descrita corresponde aos momentos pedagógicos freireanos: investigação temática/problematização da realidade, sistematização de conceitos e aplicação crítica dos conhecimentos, alinhando-se à perspectiva de Paulo Freire.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-06-b', 'q-pnd25-06', '1. apresentar um vídeo que mostre os grupos de trabalho e os objetivos da COP30; 2. utilizar um modelo de estufa de plantas a fim de estudar o ciclo hidrológico; 3. aplicar atividades que ajudem os estudantes a fixar o conhecimento da temática abordada na letra de canção.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-06-c', 'q-pnd25-06', '1. realizar um levantamento prévio das ideias dos estudantes sobre os problemas ambientais trazidos no rap Chuva Ácida; 2. organizar os subsunçores que contribuem para estudar o tema; 3. promover uma exposição de cartazes para a comunidade considerando as soluções mitigadas na COP30.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-06-d', 'q-pnd25-06', '1. apresentar o vídeo do rap Chuva Ácida abordando os assuntos sobre mudanças climáticas; 2. organizar a Zona de Desenvolvimento Proximal, problematizando a interação entre os estudantes que sabem mais sobre o tema; 3. preparar uma exposição apresentando as soluções mitigadas na COP30.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-07', 'top-fgd-10', 'O acesso à internet e aos recursos tecnológicos, como dispositivos móveis e outros, vem crescendo na atualidade, impactando os sistemas educacionais no Brasil e no mundo. Com isso, o uso de Metodologias Ativas foi intensificado, visando atender às diferentes demandas da comunidade escolar. Muitas dessas metodologias são implementadas via plataformas digitais, excluindo uma parcela considerável de estudantes que não têm acesso a tais plataformas devido a desigualdades sociais, conforme apontam dados do Instituto Brasileiro de Geografia e Estatística (IBGE). Os dados indicam que cerca de 60% das pessoas não possuem acesso à internet devido aos altos custos dos serviços e dos equipamentos.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-07-a', 'q-pnd25-07', 'uma aula expositiva realizada pelo professor que aborde o tema de tecnologias, seguida de exercícios de múltipla escolha.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-07-b', 'q-pnd25-07', 'jogos desplugados produzidos pelos estudantes, seguidos da socialização das aprendizagens em uma plenária.', true, 'Jogos desplugados dispensam o acesso à internet e a dispositivos digitais, permitindo o uso de metodologias ativas sem excluir estudantes com menor acesso a tecnologias.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-07-c', 'q-pnd25-07', 'leitura de um texto de referência sobre tecnologias proposta pelo professor, seguida de uma avaliação.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-07-d', 'q-pnd25-07', 'uma aula gamificada com seus dispositivos móveis planejada pelos estudantes, seguida da socialização dos resultados.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-08', 'top-fgd-14', 'A Educação do Campo emerge da discussão de diálogos com movimentos sociais e em diferentes eventos, como as Conferências Nacionais por uma Educação Básica do Campo. Normativas foram promulgadas, tais como a Resolução CEB/CNE n. 1/2002, que institui Diretrizes Operacionais para a Educação Básica nas Escolas do Campo, em prol de um projeto que continue a “luta para que os sistemas de ensino discutam um currículo para a área rural e que a formação de professores, inicial, continuada ou em serviço, não reproduza o currículo da área urbana na rural”.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-08-a', 'q-pnd25-08', 'subordinar a cultura, as memórias e a luta do povo do campo à história urbana.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-08-b', 'q-pnd25-08', 'identificar os conhecimentos das comunidades do campo, que contrariam o currículo instituído.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-08-c', 'q-pnd25-08', 'vincular o ensino ao trabalho e desconsiderar os saberes produzidos no contexto escolar urbano.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-08-d', 'q-pnd25-08', 'reconhecer o campo como lugar de vida e de produção que sofreu com um projeto de desenvolvimento exploratório.', true, 'A formação docente para a Educação do Campo parte do reconhecimento do campo como território de vida, cultura e produção, historicamente marginalizado por um modelo de desenvolvimento exploratório, e não da subordinação ao currículo urbano.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-09', 'top-fgd-02', 'A História da Educação no Brasil pode ser organizada em períodos com características específicas de paradigmas educacionais de cada época, a exemplo da Escola Nova (décadas de 1920-1930), cujas práticas pedagógicas', 'facil', 'PND_2025_OFICIAL', 2025, 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/prova-nacional-docente/provas-e-gabaritos', 'Formação Geral Docente — História da educação (FGD-II)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-09-a', 'q-pnd25-09', 'tinham uma visão filosófica essencialista de sujeito e uma perspectiva didática centrada no professor.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-09-b', 'q-pnd25-09', 'partiam do pressuposto da neutralidade científica, inspiradas nos princípios da racionalidade e da eficiência.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-09-c', 'q-pnd25-09', 'promoviam o aprendizado do português para os indígenas e seguiam ancoradas na doutrina cristã.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-09-d', 'q-pnd25-09', 'centralizavam a educação nas vivências, nas estratégias de ensino e no interesse do estudante.', true, 'A Escola Nova rompeu com o modelo tradicional centrado no professor, valorizando o interesse, a experiência e a atividade do estudante no processo de aprendizagem.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-10', 'top-fgd-16', 'Texto para questões 10 e 11
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-10-a', 'q-pnd25-10', 'priorizam os conteúdos disciplinares específicos como estratégia motivadora educacional.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-10-b', 'q-pnd25-10', 'favorecem a experiência de estudantes, enfatizando saberes de uma área de conhecimento.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-10-c', 'q-pnd25-10', 'incentivam a valorização do mundo do trabalho com base em metodologias de ensino inovadoras.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-10-d', 'q-pnd25-10', 'integram as vivências dos estudantes ao currículo, promovendo reflexões sobre o mundo do trabalho.', true, 'Os professores partiram das vivências profissionais dos estudantes de EJA para articular conteúdos curriculares de diferentes áreas, promovendo reflexão crítica sobre o mundo do trabalho.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-11', 'top-fgd-14', 'Texto para questões 10 e 11
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-11-a', 'q-pnd25-11', 'formação pedagógica que considera o papel do professor-supervisor como coformador.', true, 'No relato, o professor-supervisor orienta e compartilha a experiência com os estagiários, atuando como coformador no processo de formação inicial docente durante o Estágio Supervisionado.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-11-b', 'q-pnd25-11', 'interação entre professor-supervisor e estagiários para a aquisição dos conteúdos curriculares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-11-c', 'q-pnd25-11', 'aquisição de novas tecnologias pelo professor-supervisor para a aplicação em sala de aula.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-11-d', 'q-pnd25-11', 'aplicação de conhecimentos teórico-metodológicos do professor-supervisor no cotidiano escolar.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-12', 'top-fgd-06', 'Texto para questões 12 e 13
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-12-a', 'q-pnd25-12', 'realizar um levantamento sobre o desperdício na alimentação escolar e divulgá-lo em um evento científico.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-12-b', 'q-pnd25-12', 'mapear os locais de descarte de alimentos e elaborar uma redação sobre o uso dos resíduos gerados.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-12-c', 'q-pnd25-12', 'pesquisar o uso de adubos orgânicos e analisar dados estatísticos sobre os benefícios da compostagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-12-d', 'q-pnd25-12', 'organizar uma oficina para o reaproveitamento de alimentos e acompanhar as mudanças comportamentais na escola.', true, 'Essa é a única alternativa que representa uma intervenção concreta e prática no contexto escolar, e não apenas atividades de registro, pesquisa ou divulgação.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-13', 'top-fgd-15', 'Texto para questões 12 e 13
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-13-a', 'q-pnd25-13', 'roda de conversa que aborde ações relacionadas ao valor nutricional dos alimentos, seguida pela aplicação de uma prova objetiva sobre os conceitos necessários para a realização dessas ações.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-13-b', 'q-pnd25-13', 'exposição de banners informativos que apresentem os tipos de alimentos utilizados nas composteiras, seguida por um mapa mental sobre o reaproveitamento da alimentação escolar.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-13-c', 'q-pnd25-13', 'debate que aborde a insegurança alimentar com base nas reflexões provocadas ao longo do projeto, seguido pela produção de um artigo de opinião a ser publicado no jornal da escola.', true, 'O debate crítico sobre insegurança alimentar articulado à produção de um artigo de opinião representa uma avaliação coerente com uma perspectiva crítica de ensino, valorizando a reflexão e a expressão argumentativa dos estudantes.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-13-d', 'q-pnd25-13', 'questionário acerca dos tipos de alimentos consumidos pela comunidade escolar, seguido pela montagem de uma composteira conforme orientações de um manual técnico.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-14', 'top-fgd-19', 'Com a intenção de valorizar a presença de estudantes indígenas em uma turma do Ensino Médio, uma professora de Filosofia apresentou o pensamento do escritor indígena Daniel Munduruku: “um caçador aprende com um caçador mais experiente; um jovem aprende sua arte na medida em que é capaz de reproduzir a arte dos mais velhos”. Essa ideia aborda diferentes formas de transmissão de conhecimento por meio da oralidade e da experiência cotidiana.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-14-a', 'q-pnd25-14', 'Elaborar um estudo de caso que exemplifique o uso atual da tapioca na comunidade urbana como forma de validar as práticas agrícolas contemporâneas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-14-b', 'q-pnd25-14', 'Apresentar vídeos gravados com a participação da comunidade escolar, registrando técnicas ancestrais e contemporâneas de se fazer tapioca.', true, 'Essa proposta efetivamente envolve a participação ativa da comunidade (famílias, escola) no registro de saberes, fomentando a cooperação entre escola, família e comunidade.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-14-c', 'q-pnd25-14', 'Construir um mural escolar com depoimentos de nutricionistas que sugerem o consumo da tapioca nas dietas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-14-d', 'q-pnd25-14', 'Transcrever as falas dos entrevistados sobre as práticas ancestrais agrícolas para análise nas aulas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-15', 'top-fgd-22', 'Uma professora, diante da existência de um aterro no entorno da escola, decidiu abordar o tema da sustentabilidade e do descarte consciente com seus estudantes. Para isso, solicitou que eles elaborassem um projeto, e a turma sugeriu as seguintes ações:
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-15-a', 'q-pnd25-15', 'normalizam o consumo e o acúmulo de bens como origem da produção dos resíduos.', true, 'Ao trocar materiais recicláveis por brindes, a proposta acaba reforçando a lógica de consumo e acúmulo de bens como natural, sem problematizar as causas estruturais da geração de resíduos, o que é uma limitação apontada por uma perspectiva crítica da Educação Ambiental.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-15-b', 'q-pnd25-15', 'proporcionam uma mudança comportamental em relação ao descarte dos resíduos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-15-c', 'q-pnd25-15', 'prejudicam o trabalho dos catadores que têm a coleta dos resíduos como fonte de renda.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-15-d', 'q-pnd25-15', 'preservam o ambiente ao deslocar os resíduos do entorno escolar para outra área.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-16', 'top-fgd-20', 'Em uma escola localizada em território quilombola, as turmas do Ensino Médio estavam envolvidas com a festividade de Santo Antônio, padroeiro da comunidade. Um professor de História, aproveitando a situação, convidou professores de outras áreas para realizarem atividades pedagógicas sobre a representatividade da festa para o Inventário Cultural Quilombola. Com a mobilização das áreas, foi proposta uma reflexão sobre a autonomia e a identidade escolar presentes no Projeto Político Pedagógico da escola.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-16-a', 'q-pnd25-16', 'realiza leituras de textos sobre a festividade para normatizar saberes na escola.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-16-b', 'q-pnd25-16', 'insere festividades contemporâneas para renovar os princípios educativos da escola.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-16-c', 'q-pnd25-16', 'promove atividades para reconhecer ritos significativos para a comunidade durante a organização da festa.', true, 'A intervenção valoriza o Inventário Cultural Quilombola ao promover o reconhecimento dos ritos e saberes da comunidade relacionados à festividade, fortalecendo a colaboração entre escola e comunidade quilombola.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-16-d', 'q-pnd25-16', 'organiza feiras com produtos industrializados para possibilitar a integração da comunidade com os espaços urbanos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-17', 'top-fgd-07', 'Em uma escola da rede pública municipal, a equipe de educadores está revisando o Projeto Político Pedagógico (PPP) à luz do novo referencial curricular do município, elaborado de acordo com a Base Nacional Comum Curricular (BNCC). Durante as reuniões, surgem diferentes percepções entre os professores: alguns compreendem que esse documento apresenta uma lista de conteúdos obrigatórios a serem cumpridos; e outros entendem que ele orienta as decisões didáticas que deverão ser adaptadas, considerando o contexto da escola e as necessidades dos estudantes. Diante dessa problemática, a coordenadora pedagógica apresenta a perspectiva do currículo moldado, segundo a reflexão de Gimeno Sacristán (2000): “O currículo moldado vai além do currículo prescrito (normativo) e do apresentado (materiais didáticos), devendo ser articulado e ressignificado de acordo com os diferentes componentes curriculares, de modo a convergir para o contexto local e regional”.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-17-a', 'q-pnd25-17', 'construção social e o professor como agente mediador no desenvolvimento curricular.', true, 'A perspectiva do currículo moldado, segundo Gimeno Sacristán, concebe o currículo como uma construção social que é ressignificada pelo professor, que atua como mediador entre o currículo prescrito e a prática em sala de aula.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-17-b', 'q-pnd25-17', 'elemento neutro e o professor como agente condutor dos referenciais curriculares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-17-c', 'q-pnd25-17', 'diretriz nacional e o professor como agente executor do currículo apresentado.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-17-d', 'q-pnd25-17', 'produto e o professor como agente educacional na apropriação curricular.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-18', 'top-fgd-07', 'Na obra Documentos de identidade: uma introdução às teorias de currículo, Tomaz Tadeu da Silva argumenta que as vertentes teóricas crítica e pós-crítica do currículo emergem como reações às limitações da teoria tradicional, que concebe o currículo como um conjunto neutro de conteúdos organizados para transmissão de conhecimento e mensuração do desempenho.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-18-a', 'q-pnd25-18', 'Pesquisa de campo e discussão sobre enfrentamento dos diversos tipos de violência no entorno escolar.', true, 'A teoria crítica do currículo valoriza a conscientização dos estudantes sobre as relações de poder e as desigualdades sociais, o que se expressa em uma proposta de pesquisa de campo e discussão crítica sobre violência, promovendo reflexão sobre mecanismos sociais estruturais.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-18-b', 'q-pnd25-18', 'Elaboração de resumo e apresentação de seminários sobre desigualdades econômicas no Brasil.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-18-c', 'q-pnd25-18', 'Leitura de textos informativos e resolução de lista de exercícios com base no material didático.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-18-d', 'q-pnd25-18', 'Exibição de documentários e realização de palestras sobre bullying na escola.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-19', 'top-fgd-20', 'Li uma história de um pesquisador europeu no começo do século XX que estava nos EUA e chegou a um território dos hopi. Ele tinha pedido que alguém daquela aldeia facilitasse o encontro dele com uma anciã que ele queria entrevistar. Quando foi encontrá-la, ela estava parada perto de uma rocha. Estava conversando com a irmã dela: uma pedra. Assim como aquela senhora hopi que conversava com a pedra, sua irmã, tem um monte de gente que fala com montanhas.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-19-a', 'q-pnd25-19', 'científicos, fundamentados em uma visão eurocêntrica dos conhecimentos tradicionais locais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-19-b', 'q-pnd25-19', 'tradicionais locais, pautados por uma visão hegemônica dos conhecimentos científicos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-19-c', 'q-pnd25-19', 'científicos, integrados com os conhecimentos tradicionais locais.', true, 'A reflexão de Krenak valoriza a integração entre os saberes tradicionais e os conhecimentos científicos, superando a hierarquização eurocêntrica entre eles.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-19-d', 'q-pnd25-19', 'tradicionais locais, subordinados aos conhecimentos científicos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-20', 'top-fgd-20', 'Durante uma aula envolvendo o ensino de história e cultura afro-brasileira e africana na Educação Básica, em atendimento ao disposto na Lei n. 10 639/2003, uma professora explorou o movimento do cinema de países africanos, que tomou corpo a partir de 1960, como forma de comunicação e instrumento de expressão cultural. Ela explicou que, nesse contexto, as produções audiovisuais contrapõem-se às narrativas coloniais e propõem novas formas de representar suas histórias, suas culturas e suas lutas. Entusiasmados com o tema, os estudantes, juntamente com a professora, decidiram realizar uma mostra de filmes produzidos em países africanos para ser apresentada à comunidade escolar. A professora orientou que os estudantes deveriam selecionar três filmes, com base em critérios relevantes na compreensão do valor das culturas africanas.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-20-a', 'q-pnd25-20', 'retratem os espaços físicos e a vida animal selvagem como elementos característicos do continente africano.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-20-b', 'q-pnd25-20', 'produzam a sensação de familiaridade no espectador com base nas narrativas audiovisuais europeias e americanas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-20-c', 'q-pnd25-20', 'reconhecem as variadas formas de expressão dos povos africanos, suas subjetividades e questões sociais associadas a esses povos.', true, 'O cinema africano contemporâneo se contrapõe às narrativas coloniais estereotipadas, valorizando a diversidade de expressões culturais, subjetividades e questões sociais dos povos africanos.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-20-d', 'q-pnd25-20', 'apresentem estereótipos relacionados a temáticas da colonização e seus impactos no modo de vida urbanizado em países africanos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-21', 'top-fgd-17', 'Justiça determina melhorias imediatas nas vias de acesso e na estrutura de escolas em assentamentos
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-21-a', 'q-pnd25-21', 'A elaboração de um projeto com base em um diagnóstico sobre a situação da rede de água para solucionar o problema.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-21-b', 'q-pnd25-21', 'A instalação mínima de redes de água e de esgotamento sanitário nas escolas para superar as condições precárias de infraestrutura.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-21-c', 'q-pnd25-21', 'A articulação da gestão escolar com as autoridades competentes em busca de ações para melhorar a infraestrutura.', true, 'Cabe à gestão escolar articular-se com órgãos e autoridades responsáveis para reivindicar e viabilizar melhorias estruturais, já que a instalação de infraestrutura básica não é atribuição direta da escola.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-21-d', 'q-pnd25-21', 'A convocação da comunidade escolar para proceder à despoluição de um rio do entorno.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-22', 'top-fgd-16', 'TEXTO 1
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-22-a', 'q-pnd25-22', 'garantir a inclusão de temas relacionados à profissionalização dos estudantes e de atividades relativas ao mundo do trabalho.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-22-b', 'q-pnd25-22', 'propor uma organização curricular que oportunize a obtenção de um diploma àquelas pessoas que não puderam frequentar a escola.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-22-c', 'q-pnd25-22', 'desenvolver projetos de letramento que integrem experiências de vida dos estudantes a temas como trabalho, identidades culturais e vivências intergeracionais.', true, 'A abordagem sistêmica da EJA reconhece o estudante como sujeito histórico e social, valorizando projetos que articulem suas vivências a temas amplos, e não apenas à certificação ou à reprodução do currículo do ensino regular.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-22-d', 'q-pnd25-22', 'elaborar uma proposta de organização curricular que assegure o cumprimento das diretrizes nacionais aos estudantes e a garantia dos mesmos conteúdos e dos mesmos métodos aplicados ao ensino regular.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-23', 'top-fgd-11', 'O letramento científico representa uma competência essencial no contexto educacional e tem como finalidade proporcionar que os indivíduos compreendam, apliquem e sejam críticos ao conhecimento científico a ser utilizado em suas vidas cotidianas.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-23-a', 'q-pnd25-23', 'fundamenta-se no rigor metodológico como respaldo para os argumentos produzidos e apresentados publicamente.', true, 'O letramento científico envolve a compreensão de que o conhecimento científico se sustenta em rigor metodológico e evidências, e não em posicionamentos individuais ou neutralidade absoluta.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-23-b', 'q-pnd25-23', 'respeita a liberdade individual e a livre tomada de decisão como direitos sobrepostos às escolhas coletivas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-23-c', 'q-pnd25-23', 'permite a refutação de resultados amplamente aceitos em função de posicionamentos individuais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-23-d', 'q-pnd25-23', 'busca a impessoalidade, a objetividade e a neutralidade, à parte de influências políticas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-24', 'top-fgd-15', 'Em uma reunião de planejamento, foi proposta uma discussão sobre os diferentes tipos de avaliação e suas aplicações no processo de ensino e de aprendizagem. Foram apresentadas as características e as funções das avaliações diagnóstica, formativa e somativa no contexto escolar. Os professores foram convidados a descrever suas práticas pedagógicas e a relacioná-las aos diferentes objetivos das avaliações.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-24-a', 'q-pnd25-24', 'inicia o ensino de frações com uma atividade de recortes de modelos de pizzas de papel divididas em partes iguais, para que os estudantes resolvam uma lista de exercícios.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-24-b', 'q-pnd25-24', 'propõe uma série de perguntas para serem respondidas pelos estudantes sobre o tema de desmatamento ilegal, com o intuito de identificar os conhecimentos prévios dos estudantes sobre o assunto.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-24-c', 'q-pnd25-24', 'oferece devolutivas para a produção coletiva de uma linha do tempo com marcos da Revolução Industrial, a fim de orientar o que pode ser aperfeiçoado no trabalho.', true, 'A avaliação formativa caracteriza-se por oferecer devolutivas ao longo do processo, orientando o que pode ser aperfeiçoado, diferentemente das avaliações diagnóstica (conhecimentos prévios) ou somativa (classificação).') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-24-d', 'q-pnd25-24', 'aplica uma prova escrita com questões objetivas e dissertativas sobre os ciclos biogeoquímicos, com a finalidade de classificar os estudantes.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-25', 'top-fgd-08', 'As avaliações externas em larga escala, como o Sistema Nacional de Avaliação da Educação Básica (Saeb), são utilizadas como instrumentos de aferição da qualidade da Educação Básica no Brasil. Seu resultado é utilizado no cálculo do Índice de Desenvolvimento da Educação Básica (Ideb) das escolas. Uma determinada escola recebeu sua nota do Ideb, e o resultado ficou abaixo da média prevista. Diante disso, a direção fez uma reunião com o corpo docente para traçar metas para a melhoria do desempenho da escola.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-25-a', 'q-pnd25-25', 'direcionar o planejamento de forma estratégica.', true, 'Os resultados de avaliações externas como o Ideb devem subsidiar o planejamento pedagógico estratégico da escola, orientando ações para a melhoria da aprendizagem, sem substituir ou reduzir áreas do currículo.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-25-b', 'q-pnd25-25', 'reduzir o espaço de determinadas áreas do currículo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-25-c', 'q-pnd25-25', 'dedicar maior atenção a conteúdos extracurriculares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-25-d', 'q-pnd25-25', 'focalizar o desenvolvimento de habilidades socioemocionais.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-26', 'top-fgd-13', 'TEXTO 1
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-26-a', 'q-pnd25-26', 'exclusão, pois o professor não dialoga diretamente com o estudante surdo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-26-b', 'q-pnd25-26', 'segregação, porque a turma não consegue se comunicar com o estudante surdo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-26-c', 'q-pnd25-26', 'inclusão, porque o estudante surdo participa regularmente das aulas com a turma.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-26-d', 'q-pnd25-26', 'integração, porque o intérprete estabelece uma relação individual com o estudante surdo.', true, 'Ao delegar exclusivamente ao intérprete a condução das atividades com o estudante surdo, sem a participação efetiva do professor regente e da turma, configura-se um processo de integração (inserção individual), e não de inclusão plena.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-27', 'top-fgd-11', 'Um professor, diante de questionamentos acerca da eficácia das vacinas na comunidade, propõe aos estudantes a realização de práticas pedagógicas sobre a relação entre o aumento da ocorrência de doenças que haviam sido erradicadas e o baixo índice de vacinação referente aos imunizantes do Programa Nacional de Imunizações (PNI). Considerando o papel da escola como espaço de promoção do letramento científico, o professor inicia um projeto de conscientização da comunidade escolar quanto à importância da atualização das carteiras vacinais e do combate à desinformação. A fim de atender aos objetivos do projeto, foi elaborada uma proposta de prática pedagógica.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-27-a', 'q-pnd25-27', 'solicitar uma pesquisa em que os estudantes façam um levantamento junto aos familiares relativo a pendências na carteira de vacinação.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-27-b', 'q-pnd25-27', 'desenvolver um projeto interdisciplinar em que os estudantes investiguem dados científicos sobre vacinação e apresentem os resultados em uma feira de ciências com a participação da comunidade escolar.', true, 'Essa proposta promove efetivamente o letramento científico ao envolver investigação, análise de dados científicos e comunicação pública dos resultados, combatendo a desinformação de forma ativa.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-27-c', 'q-pnd25-27', 'promover rodas de conversa em que os estudantes construam um espaço de escuta e reflexão coletiva sobre a importância do conhecimento para a tomada de decisão em relação à escolha das melhores vacinas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-27-d', 'q-pnd25-27', 'propor uma prática pedagógica em que os estudantes tenham acesso aos materiais informativos da campanha de vacinação organizada pela Secretaria de Saúde na própria unidade escolar.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-28', 'top-fgd-23', 'A fim de cumprir a Lei n. 14 986/2024, que inclui na Lei de Diretrizes e Bases da Educação (LDB) a “obrigatoriedade de abordagens fundamentadas nas experiências e nas perspectivas femininas nos conteúdos curriculares do ensino fundamental e médio”, um professor do Ensino Médio apresentou aos estudantes dados do Relatório “Em direção à equidade de gênero no Brasil” sobre a participação de mulheres em publicações científicas no Brasil entre 2018 e 2022:
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-28-a', 'q-pnd25-28', 'pautar as avaliações escolares em práticas meritocráticas para neutralizar tentativas de favorecimento por questões de gênero.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-28-b', 'q-pnd25-28', 'analisar os dados com o intuito de promover investigações sobre a falta de representatividade feminina em áreas de exatas.', true, 'Analisar criticamente os dados para investigar as causas da sub-representação feminina nas áreas de exatas favorece a equidade de gênero, ao contrário de discursos meritocráticos ou deterministas.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-28-c', 'q-pnd25-28', 'utilizar os dados para reforçar que as escolhas profissionais são determinadas por aptidões naturais distintas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-28-d', 'q-pnd25-28', 'promover olimpíadas científicas escolares para motivar a competição entre meninas e meninos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-29', 'top-fgd-24', 'Motivado pela revisão da Lei n. 12 711/2012, ocorrida no ano de 2023, um professor do Ensino Médio propôs uma roda de conversa, utilizando a charge de jornal como recurso mobilizador para a discussão sobre os impactos das ações afirmativas no sistema educacional brasileiro. A atividade promoveu a reflexão e a crítica sobre os princípios do Plano Nacional de Educação em Direitos Humanos (PNEDH), como o respeito à dignidade humana e o exercício da cidadania democrática no Estado de Direito.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-29-a', 'q-pnd25-29', 'reconhecer as ações afirmativas previstas em lei desvinculadas do processo histórico de formação do povo brasileiro.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-29-b', 'q-pnd25-29', 'compreender as ações afirmativas previstas em lei como uma conquista democrática decorrente da mobilização social.', true, 'A atividade, ao promover reflexão crítica sobre a Lei de Cotas e os princípios do PNEDH, favorece a compreensão das ações afirmativas como resultado de mobilização social e conquista democrática, e não como algo neutro ou desvinculado da história.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-29-c', 'q-pnd25-29', 'constatar a neutralidade dos meios de comunicação em relação ao racismo estrutural e às ações afirmativas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-29-d', 'q-pnd25-29', 'entender o debate sobre as ações afirmativas como garantia da superação da discriminação racial.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-30', 'top-fgd-24', 'O espaço escolar é um lugar de convívio. Nele encontramos não apenas as relações das pessoas com o conhecimento, mas também o aprendizado de como as pessoas se relacionam entre si e com o restante do mundo. Exatamente por isso os conflitos aparecem, e a gestão da escola deve saber como lidar com eles. Por reproduzir as lógicas sociais, encontramos, também na escola, relações que desvalorizam o que é entendido como contra-hegemônico nas culturas. E isso impacta negativamente nas pessoas negras e nas praticantes das Religiões de Matrizes Africanas. Talvez os signos de Exu e de Ogum sejam boas pistas sobre como lidar com a escola na busca de espaços menos opressivos. Essas duas divindades do panteão iorubano são vinculadas aos caminhos, à comunicação, à política, aos conflitos e, de algum modo, à própria educação. Exu e Ogum nos ensinam que a convivência não precisa de uma suposição de que todas e todos pensem do mesmo modo, desejem do mesmo modo, caminhem pelos mesmos caminhos. Mas ensinam que o mundo é criado coletivamente e que, entre conflitos e andanças, devemos preservar as diferenças.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-30-a', 'q-pnd25-30', 'abordagem da religião e da cultura iorubanas em sala de aula permite que professores e estudantes reflitam sobre os efeitos das violências materiais e simbólicas na sociedade.', true, 'O texto defende que trazer a cultura e a religiosidade de matriz africana para a sala de aula possibilita refletir sobre o racismo religioso e suas violências materiais e simbólicas, promovendo espaços escolares menos opressivos.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-30-b', 'q-pnd25-30', 'apresentação de conteúdos vinculados às religiões de matrizes africanas e a valorização do diálogo na resolução de conflitos nas escolas buscam uma identidade comum a todos os estudantes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-30-c', 'q-pnd25-30', 'concepção do ambiente escolar como espaço de convívio religioso distancia-se da função social da educação, que deve focalizar conhecimentos gerais, formação disciplinar e cidadania.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-30-d', 'q-pnd25-30', 'utilização de trechos da mitologia africana nas aulas de ensino religioso cumpre o prescrito na lei que trata do ensino da história iorubana e indígena.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-31', 'top-ped-05', 'Texto para questões de 31 a 34
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-31-a', 'q-pnd25-31', 'cópia de ilustrações e da estrutura gramatical de textos de cordéis.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-31-b', 'q-pnd25-31', 'identificação de rimas e de aliterações por meio da leitura e da escuta de textos de cordéis.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-31-c', 'q-pnd25-31', 'compreensão dos usos sociais de textos de cordéis.', true, 'Uma prática de letramento vai além da decodificação de aspectos gráficos ou fonéticos e envolve compreender os usos sociais e funcionais dos textos de cordel na cultura popular.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-31-d', 'q-pnd25-31', 'identificação de elementos fonéticos e gramaticais de textos de cordéis.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-32', 'top-ped-03', 'Texto para questões de 31 a 34
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-32-a', 'q-pnd25-32', 'reescrever cordéis e orientar um debate sobre a temática O mundo da tecnologia, comparando texto digital e texto impresso.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-32-b', 'q-pnd25-32', 'classificar os diferentes tipos de cordéis e produzir uma lista com os personagens retratados.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-32-c', 'q-pnd25-32', 'reproduzir cordéis e confeccionar um mural temático, ilustrando as suas principais partes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-32-d', 'q-pnd25-32', 'abordar a temática Patrimônios históricos e orientar a produção de cordéis para serem utilizados como registros culturais.', true, 'Essa atividade articula os fundamentos do ensino de História — produção de registros e fontes históricas e culturais — ao uso do cordel como forma de registro do patrimônio, em vez de reduzi-lo à cópia ou classificação.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-33', 'top-ped-03', 'Em seu planejamento, uma professora de Anos Iniciais utilizou o cordel como recurso para explorar conhecimentos específicos de Artes. Ela realizou uma sequência didática com o objetivo de desenvolver as diferentes unidades temáticas previstas na Base Nacional Comum Curricular (BNCC) para a área: música, teatro, artes visuais e dança. O conjunto de atividades que contempla as quatro unidades temáticas é', 'media', 'PND_2025_OFICIAL', 2025, 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/prova-nacional-docente/provas-e-gabaritos', 'Componente específico de Pedagogia — Fundamentos metodológicos do ensino de Port./Mat./Ciências/Geo./História/Artes/Ed.Física (PED-III)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-33-a', 'q-pnd25-33', 'soletração de trechos do cordel, ilustração de trechos da história, organização de sarau e jogral literários.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-33-b', 'q-pnd25-33', 'exibição de vídeos de cordéis cantados, pesquisa biográfica de autores cordelistas, interpretação e dramatização de trechos do cordel.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-33-c', 'q-pnd25-33', 'rodas de conversa, identificação de rimas, leitura e interpretação de trechos de cordéis.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-33-d', 'q-pnd25-33', 'visita a uma exposição de cordéis, leitura e canto de algumas estrofes e dramatização com coreografia de trechos do cordel.', true, 'Essa é a única alternativa que contempla, de forma integrada, as quatro unidades temáticas de Artes previstas na BNCC: artes visuais (exposição), música (canto), teatro (dramatização) e dança (coreografia).') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-34', 'top-ped-03', 'Considerando a importância do cordel como recurso didático, uma professora de Anos Iniciais usou em seu planejamento, com o objetivo de consolidar a alfabetização e o letramento e de dar sequência à unidade temática O sujeito e seu lugar no mundo, a partir da qual as crianças deverão se apropriar de algumas habilidades específicas em Geografia. Com o desenvolvimento dessa unidade temática, espera-se que os estudantes', 'media', 'PND_2025_OFICIAL', 2025, 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/prova-nacional-docente/provas-e-gabaritos', 'Componente específico de Pedagogia — Fundamentos metodológicos do ensino de Port./Mat./Ciências/Geo./História/Artes/Ed.Física (PED-III)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-34-a', 'q-pnd25-34', 'compreendam as atividades socioeconômicas e os processos produtivos culturais, gerando a reflexão sobre as mudanças no setor artístico, por meio da comparação de diferentes gêneros textuais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-34-b', 'q-pnd25-34', 'articulem diferentes tempos históricos, possibilitando a compreensão das relações entre indivíduos, por meio da descrição cartográfica das regiões, dos espaços e de suas respectivas manifestações culturais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-34-c', 'q-pnd25-34', 'ampliem a leitura de mundo, favorecendo a representação mental das diferentes regiões, por meio do estudo das coordenadas geográficas registradas em uma linha do tempo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-34-d', 'q-pnd25-34', 'fortaleçam o sentimento de pertencimento, identificando-se com a sua comunidade e respeitando os diferentes contextos socioculturais, por meio do reconhecimento das diversas manifestações culturais.', true, 'A unidade temática “O sujeito e seu lugar no mundo”, em Geografia dos Anos Iniciais, tem como foco o pertencimento e o reconhecimento identitário e cultural do estudante em seu contexto, o que é diretamente trabalhado por meio do cordel.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-35', 'top-ped-03', 'Texto para questões 35 e 36
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-35-a', 'q-pnd25-35', 'desenvolver uma pesquisa sobre as coordenadas geográficas, reconhecer e memorizar as características do território urbano onde ocorre o Círio, compreendendo como o espaço físico determina práticas culturais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-35-b', 'q-pnd25-35', 'utilizar uma linha do tempo para localizar Belém e identificar o trajeto da procissão do Círio, promovendo descrições históricas sobre os símbolos envolvidos no evento, como forma de reconhecer sua importância no contexto regional.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-35-c', 'q-pnd25-35', 'apresentar o conceito de consciência fonológica, relacionando-o a práticas culturais significativas, como o Círio de Nazaré, e incentivar pesquisas bibliográficas de sua relevância histórica e geográfica em contextos locais e globais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-35-d', 'q-pnd25-35', 'realizar atividades para explorar a realidade e as vivências sobre o Círio, analisando-o como arranjo espacial produzido por relações sociais, e compreender sua lógica em diferentes escalas com o uso de cartografia e de outras linguagens.', true, 'Os fundamentos do ensino de Geografia nos Anos Iniciais valorizam a exploração da realidade vivida, a análise do espaço como produto de relações sociais e a compreensão de fenômenos em múltiplas escalas por meio de linguagens cartográficas.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-36', 'top-ped-05', 'Texto para questões 35 e 36
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-36-a', 'q-pnd25-36', 'promover conversas em grupo sobre o tema do texto, realizar sua leitura ou utilizar sua estrutura na produção escrita, com o objetivo de respeitar o tempo natural de aquisição da escrita pelos estudantes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-36-b', 'q-pnd25-36', 'organizar atividades integradas de leitura, oralidade, escrita e análise reflexiva e contextual, articulando a exploração do conteúdo cultural do Círio e a sua relevância para o contexto local, nacional e internacional.', true, 'O desenvolvimento da linguagem escrita em contextos significativos requer a integração de práticas de leitura, oralidade, escrita e reflexão crítica sobre o conteúdo do texto, articulando-o ao seu contexto sociocultural mais amplo.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-36-c', 'q-pnd25-36', 'utilizar o texto para leitura silenciosa seguida de cópia de trechos, com ênfase em aspectos caligráficos e ortográficos, priorizando a fixação de formas gráficas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-36-d', 'q-pnd25-36', 'trabalhar o texto como apoio para análise de figuras de linguagem e estruturas gramaticais, com foco nos elementos formais da língua, analisando-os de forma abstrata.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-37', 'top-ped-03', 'Texto para questões de 37 a 40
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-37-a', 'q-pnd25-37', 'identificar formas geométricas planas e espaciais, estabelecer noções de proporção e de escala e representar o espaço observado.', true, 'A produção de uma maquete a partir do mapeamento do parque mobiliza diretamente conceitos de geometria (formas planas e espaciais), proporção e escala, fundamentos do ensino de Matemática nos Anos Iniciais.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-37-b', 'q-pnd25-37', 'reconhecer símbolos cartográficos presentes nas sinalizações do parque e interpretar as instruções que indicam os trajetos a serem percorridos pelos frequentadores.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-37-c', 'q-pnd25-37', 'utilizar as quatro operações matemáticas para preencher tabelas com os gastos com transporte e com alimentação relacionados à visita ao parque.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-37-d', 'q-pnd25-37', 'calcular probabilidades de ocorrência do uso de diferentes trajetos do parque e quantificar as formas geométricas utilizadas na representação do local.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-38', 'top-ped-03', 'Texto para questões de 37 a 40
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-38-a', 'q-pnd25-38', 'reconhecer a cadeia alimentar dos seres vivos do parque, compreendendo sua relação com a vida cotidiana dos frequentadores, por meio de uma abordagem com base em projetos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-38-b', 'q-pnd25-38', 'identificar os ciclos da água e do carbono presentes no parque e sua relação com o funcionamento do ambiente, por meio de observação dirigida e de atividades integradoras.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-38-c', 'q-pnd25-38', 'compreender a relação existente entre os componentes bióticos e abióticos do parque, identificando a ação humana e as espécies que vivem juntas, com base no estudo do meio.', true, 'A proposta sobre as relações ecológicas do ecossistema do parque, a partir do registro de elementos naturais e artificiais, corresponde ao estudo do meio e à compreensão da relação entre componentes bióticos e abióticos.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-38-d', 'q-pnd25-38', 'analisar os impactos da poluição visual e sonora no parque e sua relação com a saúde, por meio de pesquisas dirigidas na internet, de infográficos e de rodas de conversa.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-39', 'top-ped-04', 'Texto para questões de 37 a 40
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-39-a', 'q-pnd25-39', 'valoriza a ludicidade e reconhece jogos e brincadeiras como manifestações da cultura corporal que contribuem para o desenvolvimento da corporeidade.', true, 'Os fundamentos da Educação Física nos Anos Iniciais valorizam o brincar e o jogo como manifestações da cultura corporal de movimento, essenciais ao desenvolvimento da corporeidade e da expressividade das crianças.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-39-b', 'q-pnd25-39', 'valoriza o lazer, os esportes, a competitividade e reconhece a importância de suas regras e seus fundamentos na rotina escolar.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-39-c', 'q-pnd25-39', 'estimula a oralidade e reconhece jogos e brincadeiras como padrões de desempenhos corporais próprios da escolarização.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-39-d', 'q-pnd25-39', 'estimula a criatividade e reconhece jogos e brincadeiras como práticas esportivas advindas das matrizes europeia e asiática.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-40', 'top-ped-09', 'Texto para questões de 37 a 40
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-40-a', 'q-pnd25-40', 'viabilizou a aplicação prática de conhecimentos em um contexto real e tangível, facilitando o entendimento dos conceitos de diferentes disciplinas e a memorização por meio da interação direta com o ambiente do parque.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-40-b', 'q-pnd25-40', 'permitiu a diversificação dos temas abordados pelos grupos, explorando um aspecto específico do parque, garantindo a classificação dos saberes de diferentes áreas e minimizando a conexão complexa dos conteúdos curriculares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-40-c', 'q-pnd25-40', 'oportunizou a pesquisa e o acesso a múltiplas áreas do conhecimento que se conectaram em torno de uma situação real, promovendo a construção significativa e a relação entre os saberes em um contexto de aprendizagem.', true, 'A aula-passeio, ao articular diferentes áreas do conhecimento (Matemática, Ciências, Geografia, Educação Física, entre outras) em torno de uma situação real e significativa, exemplifica uma prática interdisciplinar genuína.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-40-d', 'q-pnd25-40', 'estimulou a vivência de experiências variadas, explorando o ambiente de forma livre e criativa, desenvolvendo a autonomia individual e a interação social, e organizando os conteúdos de forma disciplinar.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-41', 'top-ped-06', 'Texto para questões de 41 a 43
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-41-a', 'q-pnd25-41', 'trabalha a canção como estímulo à oralidade e à imaginação, explorando os versos por meio da escuta, da conversa e da dramatização, com mediação do professor, favorecendo a articulação com a escrita alfabética de letra cursiva.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-41-b', 'q-pnd25-41', 'explora experiências para valorizar o reconhecimento das diversidades, favorecendo a construção de sentidos sobre identidade e pertencimento.', true, 'A canção mobiliza diretamente temas de identidade negra e representatividade, de modo que o uso pedagógico coerente é valorizar o reconhecimento da diversidade e favorecer a construção de sentidos sobre identidade e pertencimento, sem reduzir a proposta a aspectos técnicos de alfabetização.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-41-c', 'q-pnd25-41', 'desenvolve atividades de exploração rítmica e de expressão corporal, favorecendo o uso de múltiplas linguagens e de tecnologias na classificação de níveis de aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-41-d', 'q-pnd25-41', 'utiliza a canção para inspirar produções escritas, visuais e sonoras, favorecendo experiências estéticas, com intervenções do professor na promoção de um modelo de aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-42', 'top-fgd-20', 'Texto para questões de 41 a 43
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-42-a', 'q-pnd25-42', 'oferecer a música como parte de um ambiente rico em estímulos visuais, permitindo que as crianças explorem livremente seus significados, respeitando seu ritmo, com foco em suas interpretações pessoais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-42-b', 'q-pnd25-42', 'utilizar a letra da música como apoio para atividades de sensibilização fonológica, trabalhando elementos como rimas e repetição, de modo a contribuir para o resgate da história e da cultura afro-brasileira.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-42-c', 'q-pnd25-42', 'promover a escuta da música como ponto de partida para momentos de expressão artística e lúdica, incentivando a criatividade infantil em propostas que incluam desenho, dança e dramatização espontânea.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-42-d', 'q-pnd25-42', 'desenvolver atividades que articulem os temas da música com o contexto social e cultural das crianças, promovendo a formação de conceitos sobre ancestralidade e pertencimento.', true, 'Reconhecer e valorizar a identidade negra exige articular os temas da canção (ancestralidade, representatividade) ao contexto social e cultural vivido pelas crianças, e não apenas usar a música como recurso lúdico ou fonológico desvinculado de seu conteúdo identitário.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-43', 'top-ped-04', 'Texto para questões de 41 a 43
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-43-a', 'q-pnd25-43', 'estimular o desenvolvimento de habilidades linguísticas e motoras por meio da repetição rítmica e da reprodução coreográfica de elementos da música, focalizando a memorização e a disciplina corporal.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-43-b', 'q-pnd25-43', 'utilizar manifestações culturais como suporte para a construção de atividades lúdicas espontâneas, evitando a interferência docente e priorizando a liberdade total da criança em suas escolhas expressivas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-43-c', 'q-pnd25-43', 'integrar expressão corporal, afetividade e imaginação em um ambiente planejado, concebendo o brincar como intencionalmente mediado para favorecer a reelaboração subjetiva das experiências vividas.', true, 'A sequência descrita (dramatização, movimento corporal e desenho a partir de sentimentos) evidencia um brincar planejado e intencionalmente mediado pela professora, que integra corpo, afeto e imaginação para que as crianças reelaborem subjetivamente suas experiências, e não uma atividade espontânea sem mediação.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-43-d', 'q-pnd25-43', 'priorizar o ensino da diversidade cultural com base na análise dos personagens históricos mencionados na canção, orientando a criança na identificação de conceitos sociopolíticos por meio da escuta crítica.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-44', 'top-ped-06', 'Texto para questões de 44 a 46
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-44-a', 'q-pnd25-44', 'explora a literatura de cordel como suporte para a prática da escrita formal, reforçando o domínio da norma-padrão e a preservação da tradição oral.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-44-b', 'q-pnd25-44', 'utiliza tecnologias como meio para explorar diferentes gêneros textuais com foco na fruição estética e na gramática, considerando o contato com as obras em suas dimensões literária e artística.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-44-c', 'q-pnd25-44', 'incentiva a leitura interpretativa do cordel com apoio de recursos digitais, considerando a memorização do conteúdo original como forma de apresentar o aprendizado.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-44-d', 'q-pnd25-44', 'valoriza a diversidade de linguagens e mídias como instrumentos complementares à leitura literária, promovendo a autoria e a compreensão crítica por meio do uso das tecnologias.', true, 'Ao propor produções diversificadas (cordéis, vídeos, tirinhas, podcasts, slides) a partir do texto literário, o professor valoriza múltiplas linguagens e mídias como recursos complementares à leitura, promovendo autoria e compreensão crítica, coerente com uma prática que articula literatura, cultura e tecnologias.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-46', 'top-ped-09', 'Texto para questões de 44 a 46
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-46-a', 'q-pnd25-46', 'elaborar uma atividade de colagem em que os estudantes montem painéis visuais com imagens que representem as cenas do texto, destacando a organização estética das produções para exposição em sala.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-46-b', 'q-pnd25-46', 'promover debates sobre carga tributária e desigualdades sociais e regionais, utilizando recursos digitais para relacionar os conteúdos históricos e geográficos à realidade dos estudantes.', true, 'A alternativa articula diretamente a temática do cordel (impostos, exploração do trabalhador) aos conteúdos de História e Geografia por meio de debate crítico e recursos digitais, promovendo pensamento crítico e conexão com a realidade dos estudantes, conforme solicitado.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-46-c', 'q-pnd25-46', 'organizar a dramatização do cordel com foco na interpretação artística e na reprodução do texto original, considerando a memorização dos diálogos e a entonação correta das falas como forma de valorizar a linguagem popular.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-46-d', 'q-pnd25-46', 'realizar a leitura coletiva do cordel, seguida da análise de dados sobre a arrecadação de impostos por estado, com o uso de mapas físicos e políticos, a fim de desenvolver habilidades técnicas de localização e de leitura cartográfica.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-47', 'top-ped-09', 'Texto para questões de 47 a 50
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-47-a', 'q-pnd25-47', 'compreender o sentido literal da palavra "sabiá"; identificar rimas ao final dos versos; e reescrever a música substituindo os animais por outros da fauna brasileira.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-47-b', 'q-pnd25-47', 'refletir sobre o sentimento de saudade e os vínculos afetivos com lugares de origem; valorizar a diversidade de paisagens brasileiras; e expressar experiências de pertencimento por meio de diferentes linguagens (oral, escrita, artística).', true, 'A alternativa mantém coerência com o objetivo declarado de explorar saudade e pertencimento, articulando reflexão afetiva, valorização da diversidade de paisagens e expressão por múltiplas linguagens, o que caracteriza um trabalho interdisciplinar genuíno.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-47-c', 'q-pnd25-47', 'memorizar a letra da música para apresentação em grupo; reproduzir oralmente a canção com entonação adequada; e classificar substantivos e adjetivos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-47-d', 'q-pnd25-47', 'analisar tecnicamente a construção poética do texto; identificar elementos biográficos do autor; e utilizar a música para ilustrar figuras de linguagem.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-48', 'top-ped-09', 'Texto para questões de 47 a 50
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-48-a', 'q-pnd25-48', 'sentimento de pertencimento e memória afetiva; características de aves brasileiras; produção de textos narrativos e poéticos sobre o lugar de origem.', true, 'Essa combinação articula conteúdos de diferentes áreas (afetividade/identidade, ciências naturais sobre a fauna, e produção textual) em torno do mesmo tema da canção, caracterizando efetivamente um plano interdisciplinar coerente com a proposta da professora.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-48-b', 'q-pnd25-48', 'classificação gramatical das palavras da música; estudo da estrutura métrica e da rítmica; formação de palavras derivadas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-48-c', 'q-pnd25-48', 'técnicas de canto e afinação vocal; estudo da música nordestina; análise de elementos rítmicos em letras de canções.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-48-d', 'q-pnd25-48', 'pontuação e uso de pronomes; identificação de sujeitos ocultos; tipos de predicado em textos poéticos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-49', 'top-fgd-06', 'Texto para questões de 47 a 50
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-49-a', 'q-pnd25-49', 'leitura compartilhada da música, com ênfase na entonação e no ritmo; ditado de palavras-chave da canção para trabalhar ortografia; discussão oral sobre o significado de expressões presentes na letra.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-49-b', 'q-pnd25-49', 'escuta atenta da música, seguida de roda de conversa sobre sentimentos e imagens despertadas; desenho do "lugar onde mora o sabiá" com base em observações e em referências culturais; produção coletiva de textos curtos sobre lugares que causam saudade.', true, 'Essa sequência mobiliza simultaneamente linguagem oral e escrita, memória afetiva, referências à natureza (o lugar do sabiá) e identidade cultural, atendendo de forma articulada às quatro dimensões apontadas no enunciado.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-49-c', 'q-pnd25-49', 'leitura individual com orientação para entonação expressiva; identificação e pesquisa de palavras novas no texto; reescrita coletiva da música, incentivando o uso de conectivos e de frases explicativas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-49-d', 'q-pnd25-49', 'cópia da letra da música para identificar rimas e aliterações; pesquisa sobre cantores tradicionais do Nordeste; confecção de mural com imagens e textos relacionados a Luiz Gonzaga e sua obra.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-50', 'top-ped-19', 'Texto para questões de 47 a 50
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-50-a', 'q-pnd25-50', 'elaboração de perguntas objetivas sobre aspectos centrais da canção para aplicação em pequenos grupos; avaliação da leitura em voz alta com foco na entonação e na expressividade; correção das produções escritas com destaque para erros ortográficos mais recorrentes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-50-b', 'q-pnd25-50', 'registros descritivos da participação em rodas de conversa e atividades de escuta e de criação; portfólio com desenhos e com textos inspirados na música e nos sentimentos que ela despertou; autoavaliação com base em perguntas abertas: "O que senti?", "O que aprendi?", "Com quem compartilhei isso?".', true, 'Registros descritivos, portfólio e autoavaliação por perguntas abertas são instrumentos típicos da avaliação formativa, pois acompanham o processo de aprendizagem de forma qualitativa e contínua, em vez de focar em acertos e erros pontuais como nas demais alternativas.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-50-c', 'q-pnd25-50', 'produção de uma linha do tempo sobre a vida do compositor com auxílio de materiais complementares; classificação das rimas da canção com base em critérios predefinidos; avaliação das produções textuais com base na organização das ideias e na presença de informações relevantes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-50-d', 'q-pnd25-50', 'confecção de um portfólio com palavras desconhecidas, a partir da letra da música; prova objetiva com foco na musicalidade e nas emoções evocadas pelo texto; análise da letra para identificação de recursos linguísticos e estilísticos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-51', 'top-ped-14', 'Uma criança de 10 anos com paralisia cerebral é estudante do 4º ano. Ao longo dos anos, na mesma escola, ela sempre teve atendimento educacional especializado, conforme a Lei n. 9.394/96 e a Lei n. 13.146/15. No contexto da educação inclusiva, discute-se o uso da tecnologia assistiva como recurso fundamental utilizado pelo profissional, com foco no desenvolvimento e na garantia de participação de estudantes com deficiência. Considerando o desenvolvimento da escrita desse estudante, a utilização de recursos de tecnologia assistiva deve incluir', 'media', 'PND_2025_OFICIAL', 2025, 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/prova-nacional-docente/provas-e-gabaritos', 'Componente específico de Pedagogia — Práticas de atendimento educacional especializado (PED-XIV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-51-a', 'q-pnd25-51', 'os recursos tecnológicos disponibilizados desde seu ingresso na educação inclusiva, incluindo tablets, celulares e computadores para dispensar o uso do lápis em atividades de escrita.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-51-b', 'q-pnd25-51', 'a comunicação alternativa e ampliada, uma tecnologia assistiva classificada como "baixa tecnologia", utilizada desde o início de seu ingresso na educação inclusiva, dispensando a prática da escrita com lápis para expressar suas ideias.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-51-c', 'q-pnd25-51', 'o apoio de uma equipe multidisciplinar junto ao atendimento educacional especializado para priorizar os registros escritos, tendo em vista as limitações da tecnologia para o processo de alfabetização.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-51-d', 'q-pnd25-51', 'o teclado programável, por ser possível ajustá-lo conforme a sensibilidade ao toque, evitando repetições ou digitação de letras indesejadas, ao longo do processo de alfabetização.', true, 'Para um estudante com paralisia cerebral, cujas dificuldades motoras podem comprometer o traçado manual, o teclado programável ajustável à sensibilidade ao toque é um recurso de tecnologia assistiva específico e adequado para apoiar o desenvolvimento da escrita ao longo da alfabetização.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-53', 'top-ped-14', 'A Lei n. 13.146/15, que versa sobre a Inclusão da Pessoa com Deficiência, garante a oferta de ensino do Sistema Braille às pessoas com deficiência visual (DV), bem como o uso de recursos de tecnologia assistiva, de forma a ampliar habilidades funcionais dos estudantes, promovendo sua autonomia e sua participação. Uma escola de Anos Iniciais, que oferece atendimento educacional especializado, recebe um estudante com DV congênita que frequenta o 3º ano e faz uso de tecnologia assistiva em sala de aula, como leitores de tela, máquinas de escrever em Braille, softwares de reconhecimento de voz, aplicativos de acessibilidade para smartphones e óculos falantes. Considerando que esse estudante apresenta autonomia no uso de recursos de tecnologia assistiva, é correto afirmar que o atendimento educacional especializado atua na', 'media', 'PND_2025_OFICIAL', 2025, 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/prova-nacional-docente/provas-e-gabaritos', 'Componente específico de Pedagogia — Práticas de atendimento educacional especializado (PED-XIV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-53-a', 'q-pnd25-53', 'função principal de auxiliar o professor regente no processo de ensino e aprendizagem, com foco especial no uso da máquina de escrever em Braille, bem como acompanhando o estudante em todas as aulas, complementando o trabalho do professor regente e garantindo um atendimento mais individualizado e eficaz.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-53-b', 'q-pnd25-53', 'garantia da participação do estudante na sociedade e na escola, eliminando barreiras físicas, comunicacionais, de aprendizagem, bem como disponibilizando recursos de acessibilidade a serem utilizados nas atividades escolares.', true, 'O atendimento educacional especializado tem como função primordial eliminar barreiras e disponibilizar recursos de acessibilidade que garantam a participação plena do estudante na escola e na sociedade, e não substituir o professor regente ou atuar apenas como suporte pontual em sala.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-53-c', 'q-pnd25-53', 'facilitação da comunicação em Libras entre o estudante e a comunidade escolar como um todo, representando uma ponte comunicativa entre a Libras e a Língua Portuguesa, garantindo que todos possam entender e participar de forma plena.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-53-d', 'q-pnd25-53', 'gestão educacional da escola, garantindo que o processo de ensino e aprendizagem esteja alinhado com as diretrizes educacionais e que a instituição ofereça um ambiente propício ao desenvolvimento do estudante.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-54', 'top-fgd-13', 'A Libras é a primeira língua das pessoas surdas. Desde cedo, elas precisam ter contato com essa língua para que seu desenvolvimento seja pleno. Não foi o caso de um estudante surdo com 10 anos matriculado no 5º ano do Ensino Fundamental que não tem fluência em Libras, nem proficiência em Língua Portuguesa, assim como seus pais, que não são fluentes em Libras. Em sua escola, ele recebe atendimento educacional especializado bilíngue, conforme a Lei n. 14.191/21. No contexto da educação inclusiva, discute-se o uso da tecnologia assistiva como recurso para o desenvolvimento e a garantia de participação de todos os estudantes com deficiência, o que se aplica também aos estudantes surdos. Considerando as informações apresentadas sobre essa mediação didático-pedagógica, para a total inclusão desse estudante, são necessários, no atendimento educacional especializado bilíngue,', 'dificil', 'PND_2025_OFICIAL', 2025, 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/prova-nacional-docente/provas-e-gabaritos', 'Formação Geral Docente — Libras, cultura e identidade surda (FGD-XIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-54-a', 'q-pnd25-54', 'a escrita de sinais e a datilologia, o uso de tecnologia assistiva para estudantes surdos, abordando Libras e Português, e a valorização da identidade e cultura surdas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-54-b', 'q-pnd25-54', 'Libras-Português, o envolvimento dos pais no uso da Libras, o foco para atender às especificidades linguísticas dos estudantes surdos, a utilização das tecnologias assistivas bilíngues Libras-Português, e a valorização das identidades e das especificidades de sua língua e cultura.', true, 'A educação bilíngue de surdos, conforme a Lei n. 14.191/21, pressupõe o ensino em Libras-Português, o envolvimento da família na comunicação em Libras, tecnologias assistivas bilíngues e a valorização da identidade e cultura surdas, atendendo de forma integral às especificidades linguísticas do estudante e de seus pais não fluentes em Libras.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-54-c', 'q-pnd25-54', 'Libras-Sinalização, a presença do tradutor-intérprete de Libras-Português para suprir a presença dos pais na comunicação familiar e o uso de tecnologias para o ensino de Português como primeira língua para o domínio da escrita e a valorização da identidade e cultura surdas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-54-d', 'q-pnd25-54', 'o tradutor-intérprete, a sala multifuncional equipada com material de tecnologia assistiva bilíngue Libras-Português, a presença obrigatória de professores surdos de Libras e de tradutores-intérpretes de Libras-Português para atuar no apoio ao trabalho do professor, e o envolvimento da família na comunicação em Libras.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-55', 'top-ped-14', 'No contexto da educação inclusiva, é importante que os professores busquem novos e diferentes conhecimentos que podem ser potencializados pelo uso das Tecnologias da Informação e Comunicação (TICs). Em uma turma de Anos Iniciais composta por 25 estudantes, três apresentam Transtorno do Espectro Autista (TEA) com atendimento educacional especializado. Diante desse cenário, a professora busca desenvolver com os estudantes habilidades sociais por meio de tecnologia assistiva. Um trabalho pedagógico voltado para o desenvolvimento das habilidades sociais com base na utilização de recursos de tecnologia assistiva e das TICs, sobretudo com estudantes com TEA, deve priorizar o(a)', 'media', 'PND_2025_OFICIAL', 2025, 'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/prova-nacional-docente/provas-e-gabaritos', 'Componente específico de Pedagogia — Práticas de atendimento educacional especializado (PED-XIV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-55-a', 'q-pnd25-55', 'utilização de recursos como edição facilitada, correção automática, visualização em tela e de recursos para facilitar a escrita para quem tem dificuldades com a caligrafia e a escrita manual; softwares de conversão de fala em texto; teclados adaptados, softwares de organização e planificação, e aplicativos de escrita com recursos de acessibilidade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-55-b', 'q-pnd25-55', 'uso de brinquedos que estimulam os sentidos, como blocos de construção, bolhas de sabão e brinquedos de borracha, possibilitando explorar diferentes sensações e melhorar a propriocepção; regulação do sistema nervoso e redução da ansiedade, proporcionando uma sensação de segurança e aumentando a capacidade de foco em atividades.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-55-c', 'q-pnd25-55', 'organização do espaço escolar com elementos visuais, como agendas e horários, ajudando a reduzir a ansiedade e facilitando a disciplina da turma; jogos educativos adaptados como ferramenta lúdica e eficaz para alfabetizar, tornando o aprendizado mais divertido e prazeroso.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-55-d', 'q-pnd25-55', 'exploração de ferramentas digitais para promover a inclusão e o desenvolvimento pessoal e social; aplicativos de comunicação com jogos que simulam situações sociais, auxiliando no reconhecimento de sinais, como expressões faciais e tom de voz, e no desenvolvimento de respostas apropriadas, além da leitura de expressões faciais ou da compreensão de emoções.', true, 'Como o objetivo é desenvolver especificamente habilidades sociais com base em tecnologia assistiva e TICs, os recursos digitais voltados à simulação de situações sociais e ao reconhecimento de sinais como expressões faciais e emoções são os mais diretamente alinhados a esse propósito, diferentemente das demais alternativas, centradas em escrita, sensações físicas ou organização espacial.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-56', 'top-ped-19', 'Texto para questões de 56 a 59
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-56-a', 'q-pnd25-56', 'as avaliações de larga escala fornecem resultados padronizados do desempenho individual dos estudantes no processo avaliativo. Sergipe alcançou índices que mostram uma considerável queda no desempenho dos estudantes do Ensino Médio, se comparado aos dados de 2021, o que reflete a ineficácia dessas avaliações em seu caráter formativo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-56-b', 'q-pnd25-56', 'o Ideb é um instrumento de avaliação externa que mede o desempenho dos estudantes das redes públicas de ensino de todo o país. Os estudantes sergipanos dos Anos Iniciais do Ensino Fundamental da rede pública estadual tiveram resultados muito satisfatórios, alcançando um nível de proficiência 0,1 ponto superior à média nacional.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-56-c', 'q-pnd25-56', 'as avaliações de larga escala permitem mapear informações importantes para a análise comparativa do desempenho dos estudantes. Em Sergipe, os dados acumulados demonstram uma evolução positiva, com o aumento da média no Ensino Fundamental em comparação aos dados de 2021.', true, 'O texto informa que a aprendizagem evoluiu em todas as etapas de ensino em Sergipe, incluindo o Ensino Fundamental, em comparação a 2021, confirmando que as avaliações de larga escala permitem esse mapeamento comparativo, ao contrário das demais alternativas, que contêm afirmações não sustentadas pelos dados apresentados.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-56-d', 'q-pnd25-56', 'o Ideb é calculado a partir das avaliações externas aplicadas em cada sistema de ensino aos estudantes da Educação Básica da rede pública. Em Sergipe, os dados são obtidos a partir dos testes aplicados anualmente pelo Saese e apontam a estagnação dos índices de desempenho desde 2021.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-57', 'top-ped-19', 'Texto para questões de 56 a 59
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-57-a', 'q-pnd25-57', 'utilizou os dados divulgados pelo Inep para analisar os fatores que influenciam o desempenho dos estudantes e para elaborar uma proposta de intervenção pedagógica com base no diagnóstico da sua realidade que identificasse as possíveis causas da nota baixa alcançada pela instituição no Ideb.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-57-b', 'q-pnd25-57', 'analisou criticamente a sua proposta pedagógica e, ao constatar a discrepância do Ideb do município em relação ao índice do estado, buscou compreender se os currículos praticados na escola apresentam equivalência com as habilidades e as competências que são avaliadas nos Anos Finais do Ensino Fundamental em todo o país.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-57-c', 'q-pnd25-57', 'priorizou o aspecto quantitativo da avaliação, ao centrar os seus esforços em transformar o currículo dos Anos Finais do Ensino Fundamental em instrumento para garantir o ensino dos conteúdos que são avaliados nos testes, gerando o empobrecimento curricular e uma visão tecnicista da educação.', true, 'A racionalidade técnica na avaliação se manifesta exatamente quando a escola reduz o currículo a um instrumento de preparação para os testes, priorizando o aspecto quantitativo e gerando empobrecimento curricular, como descrito no enunciado (treinamento, perda de autonomia docente, sobrecarga de provas).') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-57-d', 'q-pnd25-57', 'resgatou os dados do Ideb para investigar as causas das disparidades no desempenho dos estudantes no estado e formular alternativas de ações, conferindo autonomia aos professores na tomada de decisões, na revisão da proposta pedagógica e na melhoria dos processos de ensino e de aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-58', 'top-ped-05', 'Texto para questões de 56 a 59
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-58-a', 'q-pnd25-58', 'intensificar o trabalho pedagógico com o uso de diferentes portadores de textos e gêneros textuais.', true, 'Diversificar portadores de texto e gêneros textuais é uma estratégia pedagógica diretamente voltada para o desenvolvimento da proficiência leitora, ampliando o repertório e as práticas de leitura dos estudantes, de forma coerente com o uso pedagógico dos dados do Saeb.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-58-b', 'q-pnd25-58', 'priorizar o ensino de ortografia e de gramática a partir da produção de textos escritos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-58-c', 'q-pnd25-58', 'utilizar atividades lúdicas e metodologias ativas, para que os estudantes desenvolvam a oralidade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-58-d', 'q-pnd25-58', 'aplicar provas mensais e formar turmas de recuperação, para que os estudantes superem eventuais dificuldades.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-59', 'top-ped-20', 'Texto para questões de 56 a 59
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-59-a', 'q-pnd25-59', 'toma medidas para a promoção automática dos estudantes para elevar a taxa de aprovação, independentemente dos processos de ensino e da avaliação de aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-59-b', 'q-pnd25-59', 'promove ações de incentivos e premiações para os estudantes que alcançarem as maiores notas nas avaliações somativas que testam a proficiência, com base na matriz de referência do Saeb.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-59-c', 'q-pnd25-59', 'destina maior carga horária semanal às disciplinas Língua Portuguesa e Matemática, reduzindo as horas de aulas das disciplinas que não são avaliadas nos testes de larga escala.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-59-d', 'q-pnd25-59', 'reavalia periodicamente a proposta pedagógica e monitora o desempenho dos estudantes, atuando de forma propositiva e colaborativa no combate à evasão e na formação continuada dos professores.', true, 'O foco genuíno na qualidade do ensino requer que a gestão atue sobre os processos formativos como um todo — reavaliação contínua da proposta pedagógica, monitoramento do desempenho, combate à evasão e formação continuada — e não apenas sobre os componentes numéricos isolados da fórmula do Ideb, como fazem as demais alternativas.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-60', 'top-fgd-23', 'Texto para questões 60 e 61
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-60-a', 'q-pnd25-60', 'desenvolver metodologias diretivas para os adolescentes, pois eles estão em uma situação de vulnerabilidade social que limita o desenvolvimento da autonomia e a criticidade para lidar com problemas complexos, como o bullying.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-60-b', 'q-pnd25-60', 'mediar a discussão, para que os adolescentes possam expor as inquietações, as dúvidas e os conhecimentos, refletindo criticamente e desenvolvendo autonomia nas possíveis formas de resolução da situação-problema.', true, 'Ao organizar uma roda de conversa e provocar reflexões sobre a construção social dos papéis de gênero, a pedagoga atua como mediadora do diálogo, favorecendo que os próprios adolescentes reflitam criticamente e desenvolvam autonomia para lidar com a situação, sem impor respostas prontas.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-60-c', 'q-pnd25-60', 'promover metodologias ativas, como roda de conversa, para evitar conflitos e tensões, de forma a facilitar a convivência harmoniosa, baseada na pacificação das diferenças.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-60-d', 'q-pnd25-60', 'assumir o protagonismo da situação, coordenando a roda de conversa e explicando aos adolescentes sobre a importância de uniformizar as características e as habilidades de cada pessoa do grupo.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-61', 'top-fgd-10', 'Texto para questões 60 e 61
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-61-a', 'q-pnd25-61', 'a propagação de fake news no ambiente da instituição reflete as diferentes culturas, promove a pesquisa sobre as informações divulgadas em busca do conhecimento e da valorização da diversidade presente nas redes sociais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-61-b', 'q-pnd25-61', 'a reprodução de fake news pelos adolescentes reflete uma prática de alteridade na interação respeitosa com o outro e, dessa forma, eles demonstram compreensão em relação às culturas e aos grupos cujos modos de vida são diferentes dos seus.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-61-c', 'q-pnd25-61', 'as fake news se tornam especialmente perigosas ao divulgarem opiniões e valores particulares ou de um grupo específico, tornando-se referência como verdade, em que os demais grupos passam a pensar com base nesses valores, hábitos e costumes.', true, 'A alternativa correta reconhece o mecanismo central de perigo das fake news: a difusão de opiniões particulares que, por ampla circulação, ganham status de verdade e passam a influenciar o pensamento coletivo, justificando a necessidade de uma proposta pedagógica de enfrentamento crítico, e não a naturalização dessas notícias como expressão legítima de diversidade cultural.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-61-d', 'q-pnd25-61', 'os adolescentes, ao compartilharem fake news, agem a partir do relativismo cultural, reconhecendo que todas as práticas culturais, inclusive os discursos que discriminam e hierarquizam determinados grupos, devem ser preservadas em favor da convivência democrática.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-62', 'top-ped-16', 'Texto para questões de 62 a 64
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-62-a', 'q-pnd25-62', 'desenvolver um projeto de formação continuada que impulsione a reflexão crítica sobre a prática, o diálogo entre teoria e prática e a construção coletiva de soluções inovadoras e contextualizadas.', true, 'A Pedagogia como ciência da prática educativa pressupõe a articulação constante entre teoria e prática por meio da reflexão crítica e da construção coletiva de saberes, o que se concretiza em um projeto de formação continuada voltado a esses objetivos, coerente com a gestão democrática pretendida.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-62-b', 'q-pnd25-62', 'implementar um modelo de gestão que enfatize a colaboração entre professores e estudantes, priorizando o desenvolvimento de um ambiente escolar inclusivo e participativo no qual a administração atue de forma uniformizada.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-62-c', 'q-pnd25-62', 'estimular os coordenadores a assumirem a responsabilidade pela resolução dos problemas da escola, confiando em sua capacidade de encontrar soluções adequadas para os desafios.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-62-d', 'q-pnd25-62', 'direcionar os esforços para criar um ambiente centralizado que envolva a comunidade escolar em eventos e em atividades, buscando maior reconhecimento e valorização local.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-63', 'top-ped-20', 'Texto para questões de 62 a 64
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-63-a', 'q-pnd25-63', 'contratar uma consultoria especializada para elaborar o PPP, buscando agilizar o processo e garantir a qualidade técnica do documento, com a colaboração da equipe gestora da escola municipal.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-63-b', 'q-pnd25-63', 'adaptar o PPP de uma escola-modelo, buscando otimizar o tempo e os recursos na elaboração do documento, por meio de uma análise da realidade e das necessidades locais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-63-c', 'q-pnd25-63', 'promover um diagnóstico participativo que envolva os diversos segmentos da comunidade escolar, buscando identificar problemas e potencialidades, por meio de instrumentos como entrevistas, questionários e reuniões com os diferentes atores.', true, 'Uma postura investigativa e científica na construção do PPP exige o levantamento sistemático de dados junto à comunidade escolar por meio de instrumentos de pesquisa (entrevistas, questionários, reuniões), o que caracteriza um diagnóstico participativo, e não a simples adaptação ou terceirização do documento.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-63-d', 'q-pnd25-63', 'elaborar o PPP com base no controle da equipe gestora, buscando assegurar a coerência e a objetividade do plano de ação, com a contribuição dos demais membros da escola municipal.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-64', 'top-fgd-10', 'Texto para questões de 62 a 64
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-64-a', 'q-pnd25-64', 'desenvolver um projeto de letramento midiático, preparando a comunidade escolar para identificar e combater as notícias falsas por meio de verificação, análise crítica e produção de conteúdo informativo.', true, 'O letramento midiático, baseado em verificação, análise crítica e produção de conteúdo informativo, é a estratégia coerente com uma postura investigativa e científica de combate às fake news, diferentemente de medidas proibitivas ou de coibição do uso de tecnologias.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-64-b', 'q-pnd25-64', 'implementar diretrizes precisas para a coibição das tecnologias digitais na escola, visando promover um ambiente virtual mais seguro e produtivo para o aprendizado e a interação cidadã.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-64-c', 'q-pnd25-64', 'proibir campanhas de conscientização sobre os riscos das notícias falsas, buscando sensibilizar toda a comunidade escolar sobre a importância de verificar as informações antes de compartilhá-las.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-64-d', 'q-pnd25-64', 'estimular o debate sobre o papel da inteligência artificial, possibilitando desenvolver o pensamento homogêneo e a capacidade de análise dos estudantes a partir de aula expositiva.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-65', 'top-fgd-07', 'Texto para questões de 65 a 67
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-65-a', 'q-pnd25-65', 'priorizar competências empreendedoras, com foco no retorno econômico e na inserção no mercado de trabalho.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-65-b', 'q-pnd25-65', 'problematizar visões utilitaristas, com foco na valorização da diversidade social e na promoção da transformação da realidade existente.', true, 'Na perspectiva crítica de currículo, a prática pedagógica deve problematizar visões utilitaristas — como a defendida por Manolito na tirinha — valorizando a diversidade social e voltando-se para a transformação da realidade, e não para a reprodução ou a naturalização da ordem social vigente.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-65-c', 'q-pnd25-65', 'organizar conteúdos de forma objetiva e padronizada, garantindo acesso igualitário ao saber escolar tradicional.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-65-d', 'q-pnd25-65', 'considerar os contextos e as subjetividades dos sujeitos, transmitindo saberes que sustentem a ordem social vigente.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-66', 'top-fgd-20', 'Texto para questões de 65 a 67
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-66-a', 'q-pnd25-66', 'adoção de práticas pedagógicas que valorizem as línguas maternas, os saberes tradicionais e os modos de ensinar e de aprender das comunidades.', true, 'A Constituição Federal de 1988 e a LDB garantem à Educação Escolar Indígena o direito a uma educação específica, diferenciada, intercultural e bilíngue, que valoriza línguas maternas, saberes tradicionais e processos próprios de ensino e aprendizagem das comunidades indígenas.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-66-b', 'q-pnd25-66', 'participação das comunidades, preparando os povos indígenas para a assimilação cultural e para o ingresso no mercado de trabalho.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-66-c', 'q-pnd25-66', 'uso de metodologias ativas, com foco na monocultura e no uso de tecnologias digitais para a disseminação de suas culturas e de suas identidades.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-66-d', 'q-pnd25-66', 'acesso integral aos conteúdos previstos na Base Nacional Comum Curricular (BNCC) e a promoção da entrada em escolas regulares urbanas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-67', 'top-fgd-21', 'Texto para questões de 65 a 67
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-67-a', 'q-pnd25-67', 'priorizar a gestão do currículo e solicitar silêncio imediato para não comprometer o cronograma da aula, deixando para resolver o conflito de forma privada e administrativa com os envolvidos após o término do período.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-67-b', 'q-pnd25-67', 'utilizar a estratégia com foco na vítima e retirar o estudante hostilizado da sala para uma conversa de apoio, aconselhando-o sobre como se fortalecer, ignorar ou reagir às provocações de forma mais assertiva.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-67-c', 'q-pnd25-67', 'adotar uma abordagem punitiva e interromper a aula, identificando os agressores e aplicando uma advertência formal, a fim de demonstrar que tal comportamento é intolerável e de desestimular a sua repetição.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-67-d', 'q-pnd25-67', 'usar o conflito como objeto de aprendizagem coletiva e problematizar a relação entre valores éticos e consumo, conscientizando o grupo pela construção de um ambiente respeitoso.', true, 'As práticas restaurativas buscam transformar o conflito em oportunidade de aprendizagem coletiva, promovendo o diálogo e a responsabilização do grupo, em vez de recorrer a punições isoladas ou de focar apenas na vítima, por isso a alternativa que problematiza coletivamente valores e consumo é a coerente com esse princípio.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-68', 'top-fgd-04', 'Texto para questões de 68 a 70
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-68-a', 'q-pnd25-68', 'capacidade da criança de resolver problemas complexos de forma autônoma, sem qualquer tipo de auxílio externo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-68-b', 'q-pnd25-68', 'diferença entre o que a criança já consegue fazer sozinha e o que ela pode realizar com a mediação de pessoas mais experientes.', true, 'A ZDP, na teoria de Vigotski, corresponde exatamente à distância entre o nível de desenvolvimento real (o que a criança faz sozinha) e o nível de desenvolvimento potencial (o que ela consegue realizar com mediação de alguém mais experiente), como ocorre na situação descrita.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-68-c', 'q-pnd25-68', 'etapa do desenvolvimento em que as funções cognitivas da criança estão totalmente maduras e consolidadas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-68-d', 'q-pnd25-68', 'habilidade inata da criança para imitar o comportamento de adultos e dos pares, sem a necessidade de compreensão do processo.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-69', 'top-fgd-04', 'Texto para questões de 68 a 70
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-69-a', 'q-pnd25-69', 'desenvolver a capacidade de autocorreção e a independência na resolução de problemas por meio da exposição repetida a desafios gradualmente mais complexos e com intervenção do adulto.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-69-b', 'q-pnd25-69', 'identificar o nível de desenvolvimento predominante de cada criança e suas dificuldades específicas a fim de adaptar o currículo de forma homogênea.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-69-c', 'q-pnd25-69', 'assegurar que as crianças dominem as habilidades básicas do quebra-cabeça antes de avançarem para atividades mais complexas, reforçando a base do aprendizado por estágios de prontidão.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-69-d', 'q-pnd25-69', 'promover a apropriação de modos de pensar e de elementos culturais por meio da interação social mediada, possibilitando a transição do nível de desenvolvimento potencial para o real.', true, 'Ao fazer perguntas, sugerir estratégias e oferecer ajudas, a professora medeia socialmente a construção do conhecimento, permitindo que a criança se aproprie de modos de pensar e elementos culturais, transitando do que consegue fazer com apoio (potencial) para o que passa a fazer sozinha (real), núcleo do conceito vigotskiano de mediação.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-70', 'top-ped-19', 'Texto para questões de 68 a 70
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-70-a', 'q-pnd25-70', 'relatórios ou pareceres descritivos que explicitem o processo de aprendizagem da criança.', true, 'Coerente com a perspectiva histórico-cultural de Vigotski, a avaliação na Educação Infantil deve acompanhar o processo de desenvolvimento da criança, o que se materializa em relatórios ou pareceres descritivos, e não em testes padronizados, fichas classificatórias ou instrumentos que apenas comparam ou mensuram estágios fixos.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-70-b', 'q-pnd25-70', 'testes psicométricos que demonstrem o nível cognitivo de cada criança.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-70-c', 'q-pnd25-70', 'jogos e brincadeiras espontâneas que potencializem as singularidades de cada criança.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-70-d', 'q-pnd25-70', 'fichas classificatórias que comparem o desenvolvimento individual.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-71', 'top-ped-05', 'Texto para questões de 71 a 75
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-71-a', 'q-pnd25-71', 'propor a análise crítica das palavras e dos temas identificados na letra da música, buscando compreender seus significados sociais e culturais, a fim de valorizar a expressão oral e escrita.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-71-b', 'q-pnd25-71', 'desafiar os estudantes a superar a visão ingênua de mundo e a desenvolver uma postura crítica com base na letra da música, tornando-se capaz de transformar a realidade, a fim de produzir textos orais e escritos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-71-c', 'q-pnd25-71', 'explorar as palavras e os temas mais relevantes do universo destes estudantes em relação à letra da música, incluindo o vocabulário e a realidade da comunidade, a fim de culminar em um texto oral e escrito como resultado dessa exploração.', true, 'Na fase de investigação do método Paulo Freire, o professor levanta as palavras e os temas geradores do universo vocabular dos próprios estudantes, o que corresponde a explorar palavras e temas relevantes ligados à realidade da comunidade a partir da música, etapa anterior à tematização e à problematização.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-71-d', 'q-pnd25-71', 'solicitar aos estudantes que circulem as palavras que conhecem, criando uma lista para, em seguida, formar novas palavras parecidas com as que encontraram, a fim de socializar suas listas com o grande grupo.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-72', 'top-ped-09', 'Texto para questões de 71 a 75
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-72-a', 'q-pnd25-72', 'interdisciplinar, priorizando a memorização dos conteúdos, internalizando-os a partir de repetições mediadas pelo professor, por ser o detentor dos conhecimentos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-72-b', 'q-pnd25-72', 'interdisciplinar, valorizando a reflexão crítica e a conscientização dos estudantes, incentivando-os a questionar a realidade e a buscar soluções para os problemas que os afetam.', true, 'A proposta articula Língua Portuguesa, Matemática e Ciências em torno de um mesmo tema gerador, promovendo reflexão crítica e conscientização sobre condições sociais concretas, características de uma metodologia interdisciplinar e problematizadora, e não de memorização mecânica ou de disciplinas isoladas.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-72-c', 'q-pnd25-72', 'transdisciplinar, prevendo a proposição à criação e à participação em projetos de longo prazo, em que os estudantes se envolvam na aplicação de conhecimentos específicos e no desenvolvimento de habilidades.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-72-d', 'q-pnd25-72', 'transdisciplinar, utilizando jogos para tornar a aprendizagem mais lúdica, divertida e envolvente, de forma disciplinar e próxima do conhecimento dos estudantes.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-73', 'top-ped-09', 'Texto para questões de 71 a 75
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-73-a', 'q-pnd25-73', 'insiram o estudante no centro do processo de aprendizagem, em um projeto que valorize a multiterritorialidade e a troca de experiências multiculturais em produções escritas, orais e artísticas, envolvendo a integração entre as áreas de conhecimento e tomando a letra da música como provocadora de reflexões de realidades sociais.', true, 'Metodologias ativas colocam o estudante no centro do processo, e a alternativa articula essa centralidade com a valorização da multiterritorialidade e da diversidade cultural presentes na turma, integrando Geografia e Arte a partir da música como disparadora de reflexão, o que é coerente com a interdisciplinaridade proposta pela professora.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-73-b', 'q-pnd25-73', 'focalizem a atenção no professor, valorizando o momento da aprendizagem de forma oral, escrita e artística, reconhecendo a contribuição de cada uma das disciplinas para um objetivo comum, em que a integração se encontra na letra da música, ouvida por todos, e demonstrando o padrão da realidade social.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-73-c', 'q-pnd25-73', 'insiram a avaliação no centro do processo da aprendizagem, organizando a sala de aula em uma disposição que favoreça a atenção dos estudantes no momento da exposição dos conteúdos de forma oral, escrita e artística, e valorizando a contribuição das disciplinas, em uma integração por meio da letra da música.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-73-d', 'q-pnd25-73', 'focalizem a atenção no professor, que inspira os estudantes por meio da arte musical, interpretando a letra que demonstra o quanto todos vivem a mesma realidade social e territorial, integrando os diferentes conhecimentos, e abordando um tema ou problema de forma mais abrangente e profunda.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-74', 'top-ped-04', 'Texto para questões de 71 a 75
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-74-a', 'q-pnd25-74', 'as partes do corpo de modo cooperativo ou recreativo, com foco em situações festivas, comemorativas, de confraternização, de diversão; e atividades rítmicas e expressivas que explorem gestos, ritmos, sons e música.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-74-b', 'q-pnd25-74', 'as partes do corpo de modo geral, assumindo um caráter individualizado com finalidades didáticas; e atividades rítmicas e expressivas em atividades de relaxamento para manter ou recuperar a saúde do corpo e da mente.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-74-c', 'q-pnd25-74', 'o corpo visando a percepção da própria anatomia, em exercícios rítmicos de consciência da respiração, percebendo o relaxamento e a tensão dos músculos, e sentindo as articulações da coluna vertebral, em exercícios rígidos, mecânicos e repetitivos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-74-d', 'q-pnd25-74', 'o corpo e suas sensações e emoções, valorizando a cultura corporal de movimentos por meio de vivências em jogos dramáticos e mímicas; e atividades rítmicas e expressivas que explorem gestos, ritmos, sons e música.', true, 'Considerando a temática sensível e social da música (a experiência de vida de um adolescente em situação de vulnerabilidade), a proposta de Educação Física mais coerente é a que valoriza sensações e emoções por meio de jogos dramáticos, mímicas e atividades rítmicas e expressivas, e não abordagens mecânicas, recreativas festivas ou meramente anatômicas.') on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-75', 'top-ped-03', 'Texto para questões de 71 a 75
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-75-a', 'q-pnd25-75', 'desenvolver uma relação de autoconfiança com a produção artística pessoal, relacionar a própria produção com a de outros, valorizar e respeitar a diversidade artística, cultural e estética, impulsionando-a em sua criatividade.', true, 'A sequência didática, ao encerrar com livre manifestação artística inspirada na reflexão crítica sobre a música, favorece o desenvolvimento da autoconfiança na produção pessoal, a relação com produções de outros e o respeito à diversidade artística e estética, impulsionando a criatividade da estudante, conforme seu próprio objetivo declarado.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-75-b', 'q-pnd25-75', 'conhecer, relacionar e apreciar objetos, imagens, concepções artísticas e estéticas, observar essas produções, e reproduzir inspirações famosas, tornando-se admiradora de verdadeiros artistas e de obras de artes consagradas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-75-c', 'q-pnd25-75', 'identificar e situar profissões e os profissionais de artes visuais, e observar o momento presente e as transformações históricas já ocorridas, pensando sobre o cenário profissional do futuro.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-75-d', 'q-pnd25-75', 'reconhecer e diferenciar diversas técnicas de arte, com procedimentos de pesquisa, experimentação e comunicação próprios, produzindo resenhas que retratem os caminhos para belas produções.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-76', 'top-ped-18', 'Texto para questões de 76 a 80
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-76-a', 'q-pnd25-76', 'estimular a imaginação, a oralidade e a interação social por meio de atividades lúdicas e concretas, respeitando o desenvolvimento simbólico e a necessidade de movimento.', true, 'Os Campos de Experiências da BNCC para a Educação Infantil pressupõem atividades lúdicas e concretas que respeitem o desenvolvimento simbólico e a necessidade de movimento das crianças, estimulando imaginação, oralidade e interação social, como ocorre nas rodas de leitura e no teatro de fantoches descritos no projeto.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-76-b', 'q-pnd25-76', 'priorizar a aquisição de habilidades de decodificação e a formação de leitores autônomos, visando a preparação para a alfabetização formal e o domínio da leitura e da escrita nos anos subsequentes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-76-c', 'q-pnd25-76', 'focalizar narrativas complexas, esperando que as crianças mantenham a atenção por períodos prolongados, em detrimento da interação e do movimento.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-76-d', 'q-pnd25-76', 'utilizar materiais didáticos com exercícios formais de interpretação textual, direcionando-os à verificação pontual da compreensão e do vocabulário.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-77', 'top-ped-06', 'Texto para questões de 76 a 80
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-77-a', 'q-pnd25-77', 'fomentar o contato com um repertório literário selecionado, utilizando principalmente a contação de histórias pelo professor como modelo para o desenvolvimento da fluência leitora e a apreciação gramatical.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-77-b', 'q-pnd25-77', 'utilizar as diversas atividades propostas como oportunidades para identificar o estágio de desenvolvimento das habilidades de leitura de cada criança, visando orientar intervenções pedagógicas focadas na superação de dificuldades específicas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-77-c', 'q-pnd25-77', 'promover a imersão cultural e o desenvolvimento integral dos estudantes por meio de experiências significativas com a leitura, articulando diferentes linguagens e formas de expressão.', true, 'As ações do projeto (rodas de leitura, teatro de fantoches, clubes de leitura, dramatizações, diários de leitura, encontros com autores) articulam múltiplas linguagens em torno de experiências significativas de leitura, evidenciando uma concepção de prática educativa voltada à imersão cultural e ao desenvolvimento integral, e não apenas a diagnóstico de dificuldades ou apreciação gramatical.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-77-d', 'q-pnd25-77', 'estimular a memorização de textos lidos pelos estudantes, a escolha de suas leituras e a organização de eventos literários, como os clubes de leitura, com o objetivo de ampliar o repertório individual e o prazer pela leitura independente.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-78', 'top-ped-06', 'Texto para questões de 76 a 80
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-78-a', 'q-pnd25-78', 'realização de saraus poéticos e de projetos de escrita criativa inspirados em obras lidas, utilizando um acervo literário diversificado e acessível em sala de aula.', true, 'Saraus poéticos e escrita criativa a partir de obras lidas, apoiados em um acervo literário diversificado e acessível, promovem efetivamente o letramento literário ao ampliar repertório, compreensão e prazer pela leitura, diferentemente de abordagens centradas em gramática, corpus restrito ou pressupostos de interesse intrínseco automático.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-78-b', 'q-pnd25-78', 'direcionamento da leitura para livros paradidáticos que abordem temas sociais contemporâneos, utilizando um corpus literário selecionado para aprofundamento em um gênero específico.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-78-c', 'q-pnd25-78', 'aplicação de estudos linguísticos focados na estrutura frasal e na nomenclatura gramatical como principal ferramenta para decodificar o sentido dos textos literários.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-78-d', 'q-pnd25-78', 'seleção de clássicos da literatura universal para leitura, visando a formação de um repertório cultural realista, assumindo que o contato com tais obras gerará interesse intrínseco.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-79', 'top-ped-09', 'Texto para questões de 76 a 80
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-79-a', 'q-pnd25-79', 'desenvolvimento de módulos temáticos bimestrais centrados nas obras literárias do projeto, ministrados por especialistas em literatura e oferecidos como atividades de aprofundamento no contraturno escolar.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-79-b', 'q-pnd25-79', 'indicação de um professor com notório saber em literatura com a tarefa de elaborar um roteiro de como cada disciplina pode abordar os contos, cabendo aos demais professores seguir esse planejamento em suas aulas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-79-c', 'q-pnd25-79', 'exploração de temas, personagens, cenários e conceitos das narrativas literárias e atividades, como a análise de ecossistemas de contos de fadas, o cálculo de distâncias percorridas por personagens ou a recriação de cenas.', true, 'A exploração de temas, personagens e conceitos das narrativas em conexão com conteúdos de diferentes disciplinas (como ecossistemas, cálculo de distâncias, recriação de cenas) caracteriza uma integração curricular genuína e colaborativa, ao contrário de estruturas centralizadas, extracurriculares ou hierarquizadas em um único professor coordenador.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-79-d', 'q-pnd25-79', 'planejamento de quinzenas literárias ao longo do ano letivo, durante as quais os conteúdos específicos das demais disciplinas são flexibilizados para dar prioridade às atividades desse projeto, garantindo imersão nas narrativas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-pnd25-80', 'top-ped-20', 'Texto para questões de 76 a 80
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-80-a', 'q-pnd25-80', 'gerenciar a execução das etapas do projeto, assegurando o alinhamento metodológico entre os professores, a otimização do cronograma e a garantia da uniformidade das experiências de aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-80-b', 'q-pnd25-80', 'centralizar o planejamento estratégico do projeto, provendo aos professores recursos didáticos selecionados, e assegurando a otimização e a aplicação das práticas pedagógicas em sala de aula.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-80-c', 'q-pnd25-80', 'articular a equipe docente na concepção, na implementação e no aprimoramento contínuo do projeto, oferecendo apoio pedagógico sistemático e assegurando a coerência das ações com a proposta pedagógica da escola.', true, 'Diante dos desafios relatados (manutenção da frequência das atividades e integração curricular) e da necessidade de aprimoramento contínuo, cabe à coordenação pedagógica articular colaborativamente a equipe docente, oferecendo apoio sistemático e garantindo coerência com a proposta pedagógica da escola, em vez de centralizar ou uniformizar o processo de cima para baixo.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-pnd25-80-d', 'q-pnd25-80', 'direcionar os processos de avaliação diagnóstica e somativa do projeto, com foco na análise quantitativa do progresso dos estudantes, subsidiando a elaboração de relatórios institucionais e a tomada de decisões administrativas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-01', 'top-fgd-21', 'O Estatuto da Criança e do Adolescente (Lei nº 8.069/1990) define quem são os sujeitos de direitos que merecem a proteção integral por parte da sociedade e do Estado. Nas disposições preliminares da legislação indicada, qual é a idade certa para considerar uma pessoa como criança ou adolescente?', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Educação, inclusão e direitos humanos (FGD-XXI)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-01-a', 'q-cp-aocp-01', 'Até 12 anos incompletos para crianças e entre 12 e 18 anos para adolescentes.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-01-b', 'q-cp-aocp-01', '10 anos para crianças e 21 anos para adolescentes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-01-c', 'q-cp-aocp-01', '12 anos completos para crianças e 18 anos para adolescentes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-01-d', 'q-cp-aocp-01', 'Até 16 anos para crianças e adolescentes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-01-e', 'q-cp-aocp-01', '8 anos para crianças e a partir de 11 anos para adolescente.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-02', 'top-fgd-08', 'A Lei de Diretrizes e Bases da Educação Nacional (LDB) – Lei nº 9.394/1996 define a composição dos níveis escolares que fazem parte do sistema nacional de ensino. Quais são os níveis da educação escolar nacional?', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Políticas públicas, organização, financiamento e avaliação da educação (FGD-VIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-02-a', 'q-cp-aocp-02', 'A educação básica é composta pelo ensino fundamental e ensino médio.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-02-b', 'q-cp-aocp-02', 'A educação escolar é composta por dois níveis: educação básica (formada pela educação infantil, ensino fundamental e médio) e educação superior.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-02-c', 'q-cp-aocp-02', 'O ensino fundamental é a primeira etapa da educação básica, seguida pelo ensino médio.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-02-d', 'q-cp-aocp-02', 'A educação básica tem duração mínima de 5 anos e máxima de 9 anos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-02-e', 'q-cp-aocp-02', 'A educação de jovens e adultos (EJA) é uma modalidade de ensino destinada a não concluir os estudos na idade regular.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-03', 'top-fgd-07', 'Os estudos acadêmicos que abordam as concepções curriculares apontam para a ideia de que o currículo é uma forma de reprodução das relações de poder na sociedade. Em relação às concepções curriculares e às relações de poder, assinale a alternativa INCORRETA.', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Teorias e práticas de currículo (FGD-VII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-03-a', 'q-cp-aocp-03', 'A concepção humanista-liberal defende uma educação crítica e transformadora, visando à formação de cidadãos conscientes e engajados na transformação social.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-03-b', 'q-cp-aocp-03', 'A concepção tecnicista objetiva uma educação voltada para o desenvolvimento de habilidades e de competências para o mercado de trabalho.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-03-c', 'q-cp-aocp-03', 'A concepção crítico-reprodutivista tem como objetivo uma educação que busca a transformação social; no entanto, na prática, acaba por reproduzir as desigualdades sociais, pois a escola não é neutra e, por conseguinte, reflete as mesmas relações de poder da sociedade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-03-d', 'q-cp-aocp-03', 'A concepção tradicional defende uma educação voltada para a transmissão de conteúdos considerados importantes para a formação do indivíduo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-03-e', 'q-cp-aocp-03', 'As concepções curriculares não estão vinculadas às relações de poder, elas abordam a relação entre conteúdo e forma, portanto tratam de aspectos didáticos do processo de ensino.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-04', 'top-ped-09', 'A pedagoga de uma escola pública na cidade de São Paulo, responsável por orientar o plano de trabalho docente, detectou que a maioria dos professores construía o seu planejamento de forma restrita, abordando somente os conteúdos específicos da disciplina que ministrava. Quando questionou os professores, percebeu que eles tinham dificuldade de compreender a importância da abordagem interdisciplinar. A respeito da organização do currículo e da interdisciplinaridade, assinale a alternativa correta.', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Ensino, currículo e práticas interdisciplinares (PED-IX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-04-a', 'q-cp-aocp-04', 'A abordagem interdisciplinar propõe a integração dos conteúdos das diferentes disciplinas, promovendo uma visão mais ampla e conectada do conhecimento, além de estimular a criatividade e o pensamento crítico dos alunos, podendo ser uma alternativa à organização disciplinar tradicional.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-04-b', 'q-cp-aocp-04', 'A organização disciplinar tradicional do currículo é a forma de garantir a aprendizagem dos conteúdos específicos de cada disciplina.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-04-c', 'q-cp-aocp-04', 'Uma organização interdisciplinar do currículo é limitada e impede a profundidade da aprendizagem dos conteúdos específicos de cada disciplina.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-04-d', 'q-cp-aocp-04', 'Uma abordagem interdisciplinar não é eficaz para promover a aprendizagem dos conteúdos específicos de cada disciplina.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-04-e', 'q-cp-aocp-04', 'A organização do currículo com base na interdisciplinaridade é exclusiva para escolas de ensino médio e superior.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-05', 'top-fgd-08', 'O Decreto nº 5.154/2004 estabelece bases para a Educação Profissional e Tecnológica em consonância com a lei complementar LDB nº 9.394/1996. Qual é a finalidade do Decreto de 2004 em relação à educação profissional?', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Políticas públicas, organização, financiamento e avaliação da educação (FGD-VIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-05-a', 'q-cp-aocp-05', 'Ampliar a oferta de cursos técnicos em instituições públicas.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-05-b', 'q-cp-aocp-05', 'Limitar o acesso aos cursos técnicos em instituições privadas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-05-c', 'q-cp-aocp-05', 'Reduzir a carga horária dos cursos técnicos em instituições públicas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-05-d', 'q-cp-aocp-05', 'Extinguir os cursos técnicos em instituições públicas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-05-e', 'q-cp-aocp-05', 'O decreto estabeleceu parâmetros para a oferta da educação profissional, a qual deve ser feita exclusivamente por instituições de ensino superior.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-06', 'top-ped-20', 'A escola Aliança atende alunos do ensino fundamental e médio. Nessa escola, as reuniões pedagógicas, que deveriam organizar e estruturar o planejamento pedagógico, não cumprem esse objetivo. Os professores reclamam que não sabem exatamente quais são os objetivos de aprendizagem e as habilidades que devem ser trabalhadas em cada série, que não há um cronograma de conteúdos e atividades a serem realizadas ao longo do ano letivo e que não há uma coordenação pedagógica para acompanhar o desempenho dos alunos e dos professores. A partir da situação apresentada, qual é a importância da organização do ensino e do planejamento pedagógico?', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Organização, planejamento e gestão da educação (PED-XX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-06-a', 'q-cp-aocp-06', 'A organização do ensino não é elemento fundamental para a efetivação do processo de aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-06-b', 'q-cp-aocp-06', 'O planejamento auxilia os professores a se sentirem mais produtivos, mas não impacta diretamente o aprendizado dos alunos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-06-c', 'q-cp-aocp-06', 'É essencial para garantir os objetivos de aprendizagem e a utilização eficiente dos métodos e instrumentos pedagógicos durante as atividades em sala de aula.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-06-d', 'q-cp-aocp-06', 'É útil, mas não é tão importante quanto a capacidade do professor em se adaptar às necessidades individuais dos alunos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-06-e', 'q-cp-aocp-06', 'Pode ser útil, mas é menos importante do que a qualidade de material didático utilizado.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-07', 'top-fgd-10', 'A Educação a Distância é uma modalidade de ensino que se popularizou como uma forma de acesso à educação. Essa modalidade de ensino necessita de um conjunto de técnicas e métodos, ou seja, de uma didática específica, para que se ensinem de forma clara e objetiva os conteúdos. Nessa modalidade, são utilizados amplamente os recursos tecnológicos. Qual é o impacto das tecnologias da comunicação e informação na didática da Educação a Distância?', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Tecnologias da comunicação e informação nas práticas educativas (FGD-X)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-07-a', 'q-cp-aocp-07', 'Facilitam o acesso aos conteúdos educacionais e promovem a interatividade entre os alunos e os professores.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-07-b', 'q-cp-aocp-07', 'Dificultam o engajamento dos alunos, tornando o processo de aprendizagem menos eficaz.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-07-c', 'q-cp-aocp-07', 'Substituem completamente a presença do professor, tornando-o dispensável no processo educativo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-07-d', 'q-cp-aocp-07', 'Limitam a diversidade de recursos pedagógicos, restringindo a criatividade na elaboração das aulas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-07-e', 'q-cp-aocp-07', 'São irrelevantes para a didática da Educação a Distância, pois o ensino remoto é mais eficiente sem o uso dessas tecnologias.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-08', 'top-ped-19', 'A escola ABC possui um currículo padronizado e rígido, no qual os professores não têm autonomia para adaptar as atividades de ensino às necessidades e interesses dos alunos. Além disso, os professores não recebem formação adequada para lidar com a diversidade cultural e socioeconômica dos alunos, o que pode gerar desigualdades no processo de aprendizagem. Nessa situação, é possível que os alunos não se sintam motivados a aprender e que a escola não consiga cumprir seu papel de formar cidadãos críticos e autônomos. A avaliação da aprendizagem é um dos elementos didáticos do processo de ensino e aprendizagem. Qual é a principal função da avaliação da aprendizagem?', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Políticas e práticas de avaliação (PED-XIX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-08-a', 'q-cp-aocp-08', 'Identificar alunos que precisam ser reprovados para manter a qualidade do ensino.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-08-b', 'q-cp-aocp-08', 'Mensurar de forma quantitativa o conhecimento adquirido pelos alunos e compará-los entre si.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-08-c', 'q-cp-aocp-08', 'Verificar se os objetivos educacionais foram alcançados e, se não, buscar alternativas para atingi-los.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-08-d', 'q-cp-aocp-08', 'Avaliar o desempenho individual dos alunos, sem levar em consideração o contexto social e cultural.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-08-e', 'q-cp-aocp-08', 'Promover uma competição entre os alunos e estimular a busca por notas altas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-09', 'top-fgd-06', 'O processo de ensino e aprendizagem na escola é conduzido pelos docentes, que são orientados pela equipe pedagógica. O processo de escolarização apresenta elementos didáticos fundamentais ao processo de ensino e aprendizagem. Esses elementos são responsáveis por orientar e direcionar a ação pedagógica, tornando-a mais eficaz e significativa. Quais são os elementos didáticos que orientam e direcionam a ação pedagógica e docente?', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Didática e metodologias de ensino (FGD-VI)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-09-a', 'q-cp-aocp-09', 'Conteúdo; método; avaliação; material didático; professor.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-09-b', 'q-cp-aocp-09', 'Planejamento docente e avaliação da aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-09-c', 'q-cp-aocp-09', 'Projeto Político Pedagógico e currículo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-09-d', 'q-cp-aocp-09', 'Conteúdo; currículo; avaliação da aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-09-e', 'q-cp-aocp-09', 'Planejamento docente; método; professor.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-10', 'top-fgd-18', 'O ensino médio é a etapa final da educação básica. Em 2017, com a aprovação da Base Nacional Comum Curricular (BNCC), estabeleceram-se mudanças significativas nas Diretrizes Curriculares para o Ensino Médio, que impactaram a organização curricular e a oferta das disciplinas. Atualmente, o ensino médio passa por uma reforma denominada “Novo Ensino Médio (NEM)”. Qual é a principal mudança promovida por essa reforma em relação à organização curricular das disciplinas?', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Implementação e avaliação de currículos e projetos político-pedagógicos (FGD-XVIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-10-a', 'q-cp-aocp-10', 'A inclusão de disciplinas obrigatórias como língua estrangeira e filosofia.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-10-b', 'q-cp-aocp-10', 'Obrigatoriedade da oferta de disciplinas técnicas profissionalizantes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-10-c', 'q-cp-aocp-10', 'A flexibilização curricular, permitindo que os alunos escolham as disciplinas de acordo com suas áreas de interesse, guiados pelos itinerários formativos.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-10-d', 'q-cp-aocp-10', 'Aumento do número de horas-aula por semana, visando a um maior aprofundamento do conteúdo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-10-e', 'q-cp-aocp-10', 'As disciplinas são optativas, ofertadas dentro das áreas de conhecimento: linguagens, matemática, ciências da natureza e ciências humanas, e ficam disponíveis para que os alunos façam a escolha individual.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-11', 'top-fgd-12', 'O Decreto-Lei nº 5.296/2004 institui a Política Nacional para a Integração da Pessoa Portadora de Deficiência. Qual é o objetivo desse decreto?', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Educação especial e inclusiva (FGD-XII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-11-a', 'q-cp-aocp-11', 'Assegurar a igualdade de oportunidades, a participação plena e efetiva e a inclusão social das pessoas com deficiência.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-11-b', 'q-cp-aocp-11', 'Excluir as pessoas com deficiência da sociedade, para não comprometer a sua produtividade e desenvolvimento.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-11-c', 'q-cp-aocp-11', 'Permitir que as pessoas com deficiência tenham direito a tratamentos médicos, independentemente das questões relativas à inclusão social.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-11-d', 'q-cp-aocp-11', 'Assegurar que as pessoas com deficiência tenham acesso exclusivo a programas sociais específicos implementados pelo governo federal.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-11-e', 'q-cp-aocp-11', 'Assegurar a inclusão das pessoas com deficiência em atividades esportivas de alto rendimento.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-12', 'top-fgd-17', 'A gestão escolar, no âmbito da escola pública participativa, é um modelo de gestão que envolve a comunidade escolar, incluindo professores, funcionários, pais e responsáveis e a comunidade em geral. Qual é a importância da gestão participativa no planejamento escolar?', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Planejamento, organização e gestão democrática educacional (FGD-XVII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-12-a', 'q-cp-aocp-12', 'Na gestão participativa, o gestor centraliza o controle sobre as decisões escolares para evitar erros.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-12-b', 'q-cp-aocp-12', 'A gestão participativa é importante em escolas de pequeno porte, nas quais é mais fácil envolver toda a comunidade escolar nas decisões.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-12-c', 'q-cp-aocp-12', 'A gestão participativa é utilizada como mecanismo de auditoria em escolas que apresentam problemas de gestão, nas quais é necessário um envolvimento maior da comunidade para solucionar os problemas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-12-d', 'q-cp-aocp-12', 'A gestão participativa é importante em todas as escolas, pois envolve toda a comunidade escolar no processo de tomada de decisão, o que pode resultar em uma escola mais democrática e eficiente.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-12-e', 'q-cp-aocp-12', 'A gestão participativa é importante no planejamento escolar, no entanto pode atrasar a tomada de decisão e o andamento das atividades escolares.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-13', 'top-fgd-04', 'Derivadas da psicologia, as teorias da aprendizagem são múltiplas. Em geral, indicam um conjunto de conceitos fundamentais para compreender o processo de ensino e aprendizagem e aprimorar as práticas pedagógicas que promovem o desenvolvimento dos alunos. Dentre as diversas teorias da aprendizagem, destacam-se as de Piaget, Vygotsky, Wallon e Ausubel. Qual(is) dessas teorias da aprendizagem enfatiza(m) a importância do ambiente social e cultural no processo de aprendizagem?', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Psicologia da educação (FGD-IV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-13-a', 'q-cp-aocp-13', 'Teoria de Jean Piaget (1896-1980).', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-13-b', 'q-cp-aocp-13', 'Teoria de Lev Vygotsky (1896-1934).', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-13-c', 'q-cp-aocp-13', 'Teoria de Henri Wallon (1879-1962).', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-13-d', 'q-cp-aocp-13', 'Teoria de David Ausubel (1918-2008).', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-13-e', 'q-cp-aocp-13', 'Teorias de Lev Vygotsky e David Ausubel.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-14', 'top-fgd-22', 'Imagine que você é um professor de uma escola de ensino médio e está preocupado com a falta de consciência ambiental entre os alunos. Muitos deles não têm noção dos efeitos das suas ações no meio ambiente e não se preocupam com a sustentabilidade. Além disso, a escola não possui um programa de educação ambiental garantido. A esse respeito, as Diretrizes Curriculares Nacionais para a Educação Ambiental, definidas pela Resolução nº 2/2012, visam', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Educação socioambiental (FGD-XXII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-14-a', 'q-cp-aocp-14', 'divulgar as instituições que promovem atividades educativas para a formação de cidadãos com consciência ambiental.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-14-b', 'q-cp-aocp-14', 'excluir a educação ambiental do currículo escolar, colocando esse tema como conteúdo que deve ser abordado por instituições especializadas na área.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-14-c', 'q-cp-aocp-14', 'garantir a integração da educação ambiental somente nas séries iniciais do ensino fundamental.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-14-d', 'q-cp-aocp-14', 'estimular a reflexão crítica e propositiva da inserção da Educação Ambiental na formulação, execução e avaliação dos projetos institucionais e pedagógicos das instituições de ensino.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-14-e', 'q-cp-aocp-14', 'não contemplar uma abordagem interdisciplinar e contextualizada na educação ambiental, por compreender que essa temática não é de responsabilidade da escola.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-15', 'top-fgd-24', 'A Lei nº 10.639/2003 tornou obrigatório o ensino da história e cultura afro-brasileira e africana nas escolas. Na sequência, aprovou-se a Resolução CNE/CP nº 1/2004, que estabeleceu as diretrizes curriculares nacionais para a educação das relações étnico-raciais. Sobre os objetivos das diretrizes curriculares, assinale a alternativa correta.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Educação para as relações étnico-raciais (FGD-XXIV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-15-a', 'q-cp-aocp-15', 'Promover a segregação e exclusão das pessoas negras da sociedade, enfatizando as diferenças culturais por meio do ensino.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-15-b', 'q-cp-aocp-15', 'Garantir o ensino da história da cultura local, restrita à região geográfica e aos aspectos específicos do local.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-15-c', 'q-cp-aocp-15', 'Estabelecer ações afirmativas para a inclusão de pessoas negras no mercado de trabalho.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-15-d', 'q-cp-aocp-15', 'Reconhecer e valorizar a identidade, a história e a cultura dos afro-brasileiros, bem como garantir o reconhecimento e a igualdade de valorização das raízes africanas da nação brasileira, ao lado das indígenas, europeias e asiáticas.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-15-e', 'q-cp-aocp-15', 'Valorizar a superioridade de uma cultura em detrimento de outras, o que será efetivado quando o ensino abordar todas as formas culturais.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-16', 'top-ped-14', 'As Diretrizes Operacionais para o Atendimento Educacional Especializado na Educação Básica, modalidade Educação Especial, regulamentadas pela Resolução nº 4/2009 do Conselho Nacional de Educação (CNE), fornecem orientações para a organização, oferta e realização do Atendimento Educacional Especializado (AEE) para estudantes com deficiência, transtornos globais do desenvolvimento e altas habilidades/superdotação matriculados na Educação Básica. De acordo com essa legislação, quais são os recursos de acessibilidade?', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Práticas de atendimento educacional especializado (PED-XIV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-16-a', 'q-cp-aocp-16', 'São recursos de acessibilidade aqueles que asseguram condições de acesso ao currículo dos alunos com deficiência ou mobilidade reduzida, promovendo a utilização dos materiais didáticos e pedagógicos, dos espaços, dos mobiliários e dos equipamentos, dos sistemas de comunicação e informação, dos transportes e dos demais serviços.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-16-b', 'q-cp-aocp-16', 'São considerados recursos de acessibilidade o planejamento pedagógico especializado e as salas de recursos multifuncionais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-16-c', 'q-cp-aocp-16', 'Os recursos de acessibilidade serão definidos em reunião bimestral realizada pela equipe pedagógica das escolas e devem estar previstos no Projeto Político Pedagógico.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-16-d', 'q-cp-aocp-16', 'A acessibilidade diz respeito à escolha dos materiais pedagógicos adequados para promover o processo de ensino e aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-16-e', 'q-cp-aocp-16', 'São considerados recursos de acessibilidade o Plano de Desenvolvimento Individual (PDI) e o Projeto Político Pedagógico.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-17', 'top-fgd-20', 'A Resolução nº 8/2012 define as Diretrizes Curriculares Nacionais para a Educação Escolar Quilombola na Educação Básica. Dentre os aspectos abordados nessa resolução, encontramos aspectos relativos à organização da educação escolar quilombola. Sobre o calendário da educação escolar quilombola, assinale a alternativa correta.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Histórias e culturas africanas, afro-brasileiras e indígenas (FGD-XX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-17-a', 'q-cp-aocp-17', 'O calendário para a educação escolar quilombola deverá adequar-se às peculiaridades locais, inclusive climáticas, econômicas e socioculturais, a critério do respectivo sistema de ensino e do projeto político-pedagógico da escola, sem, com isso, reduzir o número de horas letivas previsto na LDB.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-17-b', 'q-cp-aocp-17', 'A educação escolar quilombola é uma modalidade de ensino que atende as populações quilombolas rurais. Para tanto, deve considerar as condições climáticas na elaboração e definição do calendário escolar.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-17-c', 'q-cp-aocp-17', 'O calendário escolar quilombola deve ser construído a partir das demandas das populações rurais, mediante a consulta às lideranças das comunidades quilombolas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-17-d', 'q-cp-aocp-17', 'O calendário escolar para educação quilombola obedecerá à mesma organização estabelecida para as escolas regulares da educação básica no âmbito dos estados e municípios, em consonância com a Constituição Federal de 1988.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-17-e', 'q-cp-aocp-17', 'O calendário escolar para educação quilombola será definido pelas secretarias de educação no âmbito dos estados e repassado para seus respectivos municípios, que farão as adequações necessárias, após consulta às lideranças das comunidades quilombolas locais.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-18', 'top-fgd-14', 'No contexto acadêmico, a efetividade do trabalho pedagógico se expressa pelo tripé ensino, pesquisa e extensão. A pesquisa e a extensão são áreas de atuação docente, fundamentais para que o ensino seja de qualidade e esteja sempre atualizado. Imagine que, em uma universidade, o curso de Pedagogia possui um corpo docente altamente qualificado e engajado em pesquisas relevantes para a área da Educação. No entanto os estudantes do curso começam a reclamar que o conteúdo das disciplinas não está sendo aplicado de forma prática e contextualizada, o que limita sua capacidade de aplicar os conceitos em situações reais. Os professores do curso de Pedagogia, então, reconhecem que a pesquisa é importante para se manterem atualizados e informados sobre as tendências e teorias da Educação, mas entendem que o ensino e a extensão são igualmente importantes para garantir que os alunos possam aplicar essas teorias na prática. Com isso, os professores decidem incorporar mais atividades práticas e projetos de extensão em suas disciplinas, visando conectar a teoria à prática e proporcionar aos alunos a oportunidade de aplicar, em situações reais, o que aprenderam. Com essa abordagem, o curso de Pedagogia consegue promover a indissociabilidade entre o ensino, a pesquisa e a extensão. Qual é a importância da indissociabilidade entre ensino, pesquisa e extensão no trabalho pedagógico?', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Identidade e especificidades do trabalho docente (FGD-XIV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-18-a', 'q-cp-aocp-18', 'A relação entre ensino, pesquisa e extensão no trabalho pedagógico não é fator determinante e deve ocorrer de forma espontânea.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-18-b', 'q-cp-aocp-18', 'A relação entre ensino, pesquisa e extensão no trabalho pedagógico é importante apenas nos níveis escolares superiores.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-18-c', 'q-cp-aocp-18', 'A indissociabilidade entre ensino, pesquisa e extensão no trabalho pedagógico é fundamental para uma formação crítica e reflexiva do estudante.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-18-d', 'q-cp-aocp-18', 'A relação entre ensino, pesquisa e extensão no trabalho pedagógico é importante apenas para a formação de professores.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-18-e', 'q-cp-aocp-18', 'A indissociabilidade entre ensino, pesquisa e extensão no trabalho pedagógico é importante apenas para a carreira acadêmica.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-19', 'top-fgd-21', 'Imagine uma escola pública, composta por uma comunidade heterogênea, onde há diversidade étnica, cultural e religiosa entre os alunos. Nessa escola, um grupo de alunos começa a intimidar, discriminar e fazer comentários ofensivos em relação a um aluno de origem africana. O aluno e seus familiares procuram a equipe pedagógica para relatar o ocorrido e observam que o estudante está se sentindo excluído e desvalorizado, e isso tem impactado o seu desempenho acadêmico. Os responsáveis pelo estudante solicitam providências e evocam aspectos contidos nas Diretrizes Nacionais para a Educação em Direitos Humanos. Nesse caso, como as Diretrizes Nacionais para a Educação em Direitos Humanos podem ser utilizadas na escola?', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Educação, inclusão e direitos humanos (FGD-XXI)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-19-a', 'q-cp-aocp-19', 'As diretrizes devem ser utilizadas para elaborar projetos e ações de orientação junto à comunidade escolar, e promover a inclusão e a prática da educação em direitos humanos em todos os níveis de ensino.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-19-b', 'q-cp-aocp-19', 'As diretrizes devem ser utilizadas para implantar o ensino religioso nas escolas brasileiras.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-19-c', 'q-cp-aocp-19', 'As diretrizes devem ser utilizadas para orientar a implementação da Educação Especial nas escolas brasileiras.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-19-d', 'q-cp-aocp-19', 'As diretrizes devem ser utilizadas para desenvolver projetos e programas com ênfase na educação financeira.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-19-e', 'q-cp-aocp-19', 'As diretrizes devem ser utilizadas para promover os estudos étnico-raciais e de línguas estrangeiras nas escolas brasileiras.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-aocp-20', 'top-ped-13', 'A Resolução nº 3/2010 define a Educação de Jovens e Adultos (EJA) como uma modalidade de ensino que deve ser oferecida àqueles que não puderam realizar os estudos na idade regular, contemplando o ensino fundamental e médio. Sobre o objetivo das Diretrizes Operacionais para EJA, assinale alternativa correta.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.aocp.com.br', 'Concurso público — IFMA (AOCP, 2023), cargo Pedagogo — Práticas educativas para crianças, jovens, adultos e idosos (PED-XIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-20-a', 'q-cp-aocp-20', 'Estabelecer as normas para a criação de novos cursos de iniciação para jovens e adultos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-20-b', 'q-cp-aocp-20', 'Definir as competências dos professores que atuam na educação de jovens e adultos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-20-c', 'q-cp-aocp-20', 'Orientar a organização e a oferta da educação de jovens e adultos, garantindo o acesso, a permanência e a conclusão com qualidade.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-20-d', 'q-cp-aocp-20', 'Criar programas de capacitação profissional para jovens e adultos em situação de vulnerabilidade social.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-aocp-20-e', 'q-cp-aocp-20', 'Produzir material didático para os alunos e organizar a formação continuada dos professores que atuam nessa modalidade de ensino.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-01', 'top-ped-07', 'De acordo com o Art. 2º, inciso VII, da Resolução CME nº 02/2020, as unidades de Educação Infantil foram orientadas quanto ao trabalho remoto: “VII - para a Educação infantil, na faixa etária correspondente de 0 a 5 anos, deverão ser elaborados e enviados, de forma digital, roteiros de brincadeiras, atividades lúdicas, literárias, musicais e culturais.”
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-01-a', 'q-cp-fgv-01', 'Os familiares e/ou responsáveis, após a aplicação das atividades sugeridas, deveriam realizar uma avaliação on-line como forma de monitoramento da Prefeitura de São Paulo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-01-b', 'q-cp-fgv-01', 'Os familiares e/ou responsáveis precisavam realizar as atividades com os alunos e, enviar relatório das atividades para a Rede municipal de São Paulo como forma de monitoramento pedagógico.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-01-c', 'q-cp-fgv-01', 'O objetivo do envio destes materiais é que os familiares e/ou responsáveis reproduzissem experiências com as crianças, por meio das atividades sugeridas, pois também é papel dos familiares e/ou responsáveis aplicar o modelo escolar.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-01-d', 'q-cp-fgv-01', 'O Art. 2º, inciso VII, da Resolução CME nº 02/2020, foi pensado como forma de assegurar que os objetivos educacionais para a Educação Infantil, por meio da mediação dos familiares e/ou responsáveis, fossem alcançados até o final do ano letivo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-01-e', 'q-cp-fgv-01', 'A Prefeitura de São Paulo, com objetivo de não haver o distanciamento dos bebês e crianças das experiências vivenciadas no espaço educacional, enviou o material Trilhas de Aprendizagens e divulgou links e sites com sugestões de atividades/vivências que podem ser feitas pelas crianças e os familiares no período pandêmico em que estivessem em casa.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-02', 'top-fgd-10', 'Assinale a opção que evidencia o que é o Ensino Híbrido para a Rede Municipal de Ensino de São Paulo.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.fgv.br/fgvprojetos/concursos', 'Concurso público — Prefeitura de São Paulo / SME-SP (FGV, 2023), cargo Professor de Educação Infantil e Ensino Fundamental I — Tecnologias da comunicação e informação nas práticas educativas (FGD-X)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-02-a', 'q-cp-fgv-02', 'Metodologia ativa mediada, exclusivamente, pela tecnologia.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-02-b', 'q-cp-fgv-02', 'Metodologia que foi utilizada como alternativa emergencial para suprir o ensino presencial, durante o período pandêmico, inclusive autorizada pelo Conselho Nacional de Educação (CNE).', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-02-c', 'q-cp-fgv-02', 'Modalidade educacional que não busca assemelhar-se ao modo presencial, mas lança mão de diversos meios, dispostos anteriormente no remoto, para atingir os objetivos educacionais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-02-d', 'q-cp-fgv-02', 'Metodologia ativa de ensino que, entre outras possibilidades, mobiliza atividades que conjugam o virtual e o presencial, sempre de forma complementar, para atingir alguns objetivos de aprendizagem.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-02-e', 'q-cp-fgv-02', 'Processo educacional planejado, que não se parece com o presencial, em que se utilizam estratégias didáticas diversas para organizar e promover tempos, momentos, espaços, interações e aprendizagens.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-03', 'top-fgd-08', 'Assinale a opção que apresenta a forma de ensino exigida para toda a Educação Básica (à exceção do Ensino Médio), que pode – em situações emergenciais – ser suspensa, conforme prevê o Art. 32, §4º, da LDB (Lei nº 9.394/1996).', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.fgv.br/fgvprojetos/concursos', 'Concurso público — Prefeitura de São Paulo / SME-SP (FGV, 2023), cargo Professor de Educação Infantil e Ensino Fundamental I — Políticas públicas, organização, financiamento e avaliação da educação (FGD-VIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-03-a', 'q-cp-fgv-03', 'Ensino Fundamental.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-03-b', 'q-cp-fgv-03', 'Ensino Presencial.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-03-c', 'q-cp-fgv-03', 'Ensino Remoto.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-03-d', 'q-cp-fgv-03', 'Ensino Híbrido.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-03-e', 'q-cp-fgv-03', 'Ensino Básico.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-04', 'top-fgd-10', 'Segundo Christensen, Horn e Staker, autores que se dedicaram a estudar inovação nas organizações educacionais, assinale a opção que indica os modelos que podem ser considerados como Ensino Híbrido, por somar características tanto da sala de aula tradicional quanto do ensino on-line.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.fgv.br/fgvprojetos/concursos', 'Concurso público — Prefeitura de São Paulo / SME-SP (FGV, 2023), cargo Professor de Educação Infantil e Ensino Fundamental I — Tecnologias da comunicação e informação nas práticas educativas (FGD-X)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-04-a', 'q-cp-fgv-04', 'Modelo STEAM e Laboratório Rotacional.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-04-b', 'q-cp-fgv-04', 'Currículo flexível e Educação Democrática.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-04-c', 'q-cp-fgv-04', 'Laboratório Rotacional e Sala de Aula Invertida.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-04-d', 'q-cp-fgv-04', 'Educação Democrática e Sala de Aula Invertida.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-04-e', 'q-cp-fgv-04', 'Sala de Aula Invertida e Educação Democrática.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-05', 'top-ped-18', 'Segundo as Diretrizes Curriculares Nacionais da Educação Básica (BRASIL, 2013), as propostas pedagógicas de Educação Infantil devem garantir que as crianças tenham a “oportunidade para manusear gravadores, projetores, computador e outros recursos tecnológicos e midiáticos”, sendo protagonistas nesse processo.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-05-a', 'q-cp-fgv-05', 'A utilização de equipamentos tecnológicos na Educação Infantil é opcional, sendo recomendado apenas para atividades pedagógicas específicas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-05-b', 'q-cp-fgv-05', 'As propostas pedagógicas de Educação Infantil devem garantir que as crianças tenham acesso a equipamentos tecnológicos apenas em salas de informática.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-05-c', 'q-cp-fgv-05', 'A utilização de computadores em sala de aula é imprescindível para o desenvolvimento dos alunos da Educação Infantil e devem ser orientados por um professor específico.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-05-d', 'q-cp-fgv-05', 'As escolas devem ter uma sala de informática para que os alunos da Educação Infantil tenham a possibilidade de conhecer recursos tecnológicos, independentemente do contexto pedagógico, tendo como protagonista o professor.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-05-e', 'q-cp-fgv-05', 'O trabalho com a linguagem midiática na Educação Infantil deve promover o diálogo do bebê e da criança com as diferentes linguagens, não reduzindo a interação com os equipamentos como meros instrumentos técnicos, descontextualizados e desvinculados das experiências individuais e coletivas.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-06', 'top-fgd-07', 'O código EI 02 EO 03 é um exemplo de combinação alfanumérica que a Base Nacional Comum Curricular (BNCC) estabelece para organizar as aprendizagens em cada etapa de ensino da Educação Básica.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-06-a', 'q-cp-fgv-06', 'EI - Etapa de Ensino, 02 - Campo de Experiência, EO - Posição da Habilidade e 03 - Grupo por Faixa Etária.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-06-b', 'q-cp-fgv-06', 'EI - Campo de experiência, 02 - Grupo por Faixa Etária, EO - Etapa de Ensino e 03 - Posição da Habilidade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-06-c', 'q-cp-fgv-06', 'EI - Etapa de Ensino, 02 - Posição da Habilidade, EO - Campo de Experiência e 03 - Grupo por Faixa Etária.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-06-d', 'q-cp-fgv-06', 'EI - Campo de Experiência, 02 - Posição da Habilidade, EO - Etapa de Ensino e 03 - Grupo por Faixa Etária.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-06-e', 'q-cp-fgv-06', 'EI - Etapa de Ensino, 02 - Grupo por Faixa Etária, EO - Campo de Experiência e 03 - Posição da Habilidade.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-07', 'top-fgd-12', 'Para a implementação da Política de Educação Especial na Perspectiva da Educação Inclusiva, é necessário que todos os profissionais da educação atuantes nas escolas se responsabilizem pelo atendimento de cada estudante público-alvo da Educação Especial.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-07-a', 'q-cp-fgv-07', 'Promover espaços de troca sobre Educação Inclusiva, bem como a articulação entre professores, profissionais de apoio e famílias.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-07-b', 'q-cp-fgv-07', 'Especificar no Projeto Político-Pedagógico as ações para a garantia do acesso, permanência, participação plena, desenvolvimento e aprendizagem do público-alvo da educação especial.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-07-c', 'q-cp-fgv-07', 'Propiciar momentos e espaços de formação da equipe e dos colegiados de participação, oportunizando a reflexão sobre os direitos humanos e o respeito às diferenças.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-07-d', 'q-cp-fgv-07', 'Solicitar que os professores acompanhem pessoalmente seus estudantes com deficiência ao Atendimento Educacional Especializado.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-07-e', 'q-cp-fgv-07', 'Assegurar a matrícula de todos os estudantes, como direito inalienável, sendo vedadas quaisquer formas de discriminação ou cobranças indevidas para sua efetivação.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-08', 'top-fgd-10', 'No município de São Paulo, a partir de 2020, a pandemia de Covid-19 levou ao fechamento das escolas de diferentes segmentos da educação e à adoção do Ensino Híbrido, para garantir a continuidade da aprendizagem.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-08-a', 'q-cp-fgv-08', 'V – V – F.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-08-b', 'q-cp-fgv-08', 'V – F – V.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-08-c', 'q-cp-fgv-08', 'F – V – F.', false, null) on conflict (id) do nothing;
