insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-14', 'top-fgd-12', 'De acordo com a Recomendação CME 02/2022, que dispõe sobre as Diretrizes Gerais para a Educação Especial na Perspectiva Inclusiva com Abordagem Específica na Rede Municipal de São Paulo, assinale a afirmativa correta.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.fgv.br/fgvprojetos/concursos', 'Concurso público — Prefeitura de São Paulo / SME-SP (FGV, 2023), cargo Professor de Educação Infantil e Ensino Fundamental I — Educação especial e inclusiva (FGD-XII)') on conflict (id) do nothing;
