insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-19-b', 'q-cp-fgv-19', 'corrobora a teoria de Vygotsky, que considera o meio social como preponderante no desenvolvimento cognitivo dos sujeitos: as crianças aprendem ao interagirem com o meio e com outros seres.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-19-c', 'q-cp-fgv-19', 'possibilita a organização das atividades, de acordo com os centros de interesse descritos por Decroly, a partir de conteúdos divididos por matérias.', false, null) on conflict (id) do nothing;
