insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-24', 'top-ped-19', 'De acordo com a Orientação Normativa 01/2013 da Secretária Municipal de Ensino, assinale a opção que descreve corretamente o processo de avaliação na Educação Infantil.', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.fgv.br/fgvprojetos/concursos', 'Concurso público — Prefeitura de São Paulo / SME-SP (FGV, 2023), cargo Professor de Educação Infantil e Ensino Fundamental I — Políticas e práticas de avaliação (PED-XIX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-24-a', 'q-cp-fgv-24', 'Deve ser um processo contínuo de registros que permitem ao educador e à família ter um parâmetro de comparação entre a criança e seus pares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-24-b', 'q-cp-fgv-24', 'Configura-se como um instrumento interno para o professor regular sua prática docente e verificar se os alunos estão se desenvolvendo e aprendendo novos conhecimentos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-24-c', 'q-cp-fgv-24', 'Deve ser pautado por múltiplos registros, tais como relatórios, fotografias, desenhos, álbuns, entre outros, realizados por adultos e crianças.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-24-d', 'q-cp-fgv-24', 'Fundamenta-se em registros individuais de aprendizagem que determinam a promoção ou retenção da criança para a etapa subsequente de ensino.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-24-e', 'q-cp-fgv-24', 'Deve conter as etapas de desenvolvimento da criança, cabendo à unidade escolar definir a utilização de notas ou registros descritivos para fins seletivos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-25', 'top-fgd-01', 'Leia o trecho a seguir.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-25-a', 'q-cp-fgv-25', 'Intelectual, refere-se a todo o processo de apropriação das linguagens, dos conhecimentos da matemática, da lógica, da tecnologia, da análise crítica, da “leitura do mundo” e da capacidade de acessar e produzir conhecimento.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-25-b', 'q-cp-fgv-25', 'Moral, refere-se ao conjunto de normas e padrões pessoais de conduta do indivíduo que o fazem distinguir entre o certo e o errado, de acordo com modelos de comportamento, para que possa relacionar-se e viver em sociedade.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-25-c', 'q-cp-fgv-25', 'Cultural, refere-se à diversidade das expressões simbólicas, incluindo as artes, as letras, os modos de vida, as formas de viver em comunidade, os sistemas de valores, costumes, crenças e ritos tradicionais e contemporâneos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-25-d', 'q-cp-fgv-25', 'Emocional, refere-se às questões do autoconhecimento, da autoconfiança, da capacidade de interação e do sentimento de pertencimento, buscando romper a lógica do individualismo e da competitividade sem solidariedade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-25-e', 'q-cp-fgv-25', 'Física, refere-se ao corpo no contexto multicultural, levando em conta a relação do corpo e suas emoções, superando o padrão psicobiológico, que vai além do autocuidado, da atenção à saúde e da prática de atividades físicas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-26', 'top-ped-05', 'Ensinamos as crianças a traçar as letras e a formar palavras com elas, mas não ensinamos a linguagem escrita.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-26-a', 'q-cp-fgv-26', 'A aprendizagem da lecto-escritura deve ser entendida como construção de um conhecimento específico a respeito da função e do valor desse objeto cultural que é a língua escrita.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-26-b', 'q-cp-fgv-26', 'A escrita produzida pelas crianças é parte de seu esquema de assimilação da aprendizagem, isto é, conforme o seu desenvolvimento manifestado pela linguagem oral.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-26-c', 'q-cp-fgv-26', 'No processo de alfabetização e letramento, o professor deve se configurar como um modelo, ou seja, um professor-leitor, um incentivador da leitura/escrita para as crianças.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-26-d', 'q-cp-fgv-26', 'A alfabetização e o letramento devem acontecer simultaneamente desde a Educação Infantil e durante todo o processo de aprendizagem da língua escrita.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-26-e', 'q-cp-fgv-26', 'Atividades de expressão, como o desenho e a brincadeira de faz-de-conta, constituem as bases para a aquisição da escrita como um instrumento cultural complexo.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-27', 'top-ped-18', 'De acordo com a Orientação Normativa para Registro na Educação Infantil SME/COPED - 2020, o registro escrito da(o) professora(or) e a devolutiva por escrito da equipe gestora garantem', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.fgv.br/fgvprojetos/concursos', 'Concurso público — Prefeitura de São Paulo / SME-SP (FGV, 2023), cargo Professor de Educação Infantil e Ensino Fundamental I — Práticas de ensino na educação infantil (PED-XVIII)') on conflict (id) do nothing;
