insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-27-e', 'q-cp-fgv-27', 'a reflexão crítica sobre a prática, a formação permanente e o controle da documentação exigida pelas Diretorias de Ensino.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-28', 'top-fgd-06', 'As opções a seguir descrevem corretamente a contribuição do ensino de História para a formação dos educandos de acordo com o Currículo da Cidade, à exceção de uma. Assinale-a.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.fgv.br/fgvprojetos/concursos', 'Concurso público — Prefeitura de São Paulo / SME-SP (FGV, 2023), cargo Professor de Educação Infantil e Ensino Fundamental I — Didática e metodologias de ensino (FGD-VI)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-28-a', 'q-cp-fgv-28', 'Identificar os principais problemas enfrentados pela sociedade na atualidade e elaborar conjecturas a respeito de suas causas no passado.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-28-b', 'q-cp-fgv-28', 'Privilegiar a observação e a razão como meios para descrever e explicar os comportamentos humanos em diferentes civilizações, identificando uma progressão social.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-28-c', 'q-cp-fgv-28', 'Investigar quais entendimentos são necessários para dimensionar as questões contemporâneas em perspectivas históricas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-28-d', 'q-cp-fgv-28', 'Conhecer, analisar, questionar e intervir na organização da sociedade em que se vive, na perspectiva de sua diversidade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-fgv-28-e', 'q-cp-fgv-28', 'Desenvolver uma formação comprometida com a análise, posicionamento e participação diante da complexidade da realidade vivida.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-fgv-29', 'top-fgd-06', '“Independentemente da forma de ensinar, do estilo do professor e dos objetos de conhecimento, Zabala (1998) sugere que é importante considerar não apenas os conteúdos cognitivos, mas também adotar uma perspectiva ampla.”
