insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-01', 'top-ped-02', 'Em relação à gestão da educação ante às exigências de qualidade e produtividade da escola pública, Paro (2001) afirma que, na qualidade de atividade adequada a um fim, o processo pedagógico constitui verdadeiro trabalho humano, que supõe a existência de um objeto de trabalho que, no caso, é', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Trabalho e educação (PED-II)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-01-a', 'q-cp-vun-01', 'a aula em si.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-01-b', 'q-cp-vun-01', 'a cultura escolar.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-01-c', 'q-cp-vun-01', 'o próprio educando.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-01-d', 'q-cp-vun-01', 'o conteúdo curricular.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-01-e', 'q-cp-vun-01', 'a metodologia de ensino.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-02', 'top-fgd-05', 'Conforme Formosinho (2007), um exercício que a herança pedagógica dos dois últimos séculos nos permite é o de contrastar os modos de fazer pedagogia: o modo da transmissão e o modo da participação. Na pedagogia da participação, segundo Formosinho,', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Teorias pedagógicas (FGD-V)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-02-a', 'q-cp-vun-02', 'o papel do professor é estender os interesses e conhecimentos da criança e do grupo em direção à cultura.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-02-b', 'q-cp-vun-02', 'a atividade da criança é discriminar estímulos exteriores e responder corretamente às perguntas, corrigindo e evitando erros.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-02-c', 'q-cp-vun-02', 'os objetivos do ensino são adquirir capacidades pré-acadêmicas, acelerar as aprendizagens e compensar deficit.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-02-d', 'q-cp-vun-02', 'a avaliação está centrada nos produtos e na comparação das realizações individuais com o padrão estabelecido.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-02-e', 'q-cp-vun-02', 'o processo de aprendizagem significa mudança comportamental observável, realizada por meio do ensino.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-03', 'top-fgd-06', 'Ao discutir as mudanças profundas que têm ocorrido na educação nos últimos anos, Moran (2015) menciona um dos modelos mais interessantes de ensinar hoje, que concentra no ambiente virtual o que é informação básica e deixa para a sala de aula as atividades mais criativas e supervisionadas. Esse modelo é chamado de aula', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Didática e metodologias de ensino (FGD-VI)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-03-a', 'q-cp-vun-03', 'aberta.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-03-b', 'q-cp-vun-03', 'invertida.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-03-c', 'q-cp-vun-03', 'dialogada.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-03-d', 'q-cp-vun-03', 'expositiva.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-03-e', 'q-cp-vun-03', 'de demonstração.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-04', 'top-ped-18', 'Conforme Zabalza (1998), existem dois “passaportes” pedagógicos (com cinco sinais distintivos) que a escola infantil deve exibir como carteira de identidade educativa, se pretende atravessar a “fronteira” para a região onde aparece nitidamente a dupla imagem de uma elevada qualidade de vida da criança e, simultaneamente, um respeito efetivo aos seus direitos-necessidades fundamentais. Em relação ao primeiro sinal distintivo do primeiro passaporte, o autor afirma:', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Práticas de ensino na educação infantil (PED-XVIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-04-a', 'q-cp-vun-04', 'a creche necessita adotar uma concepção espontaneísta e extemporânea da experiência educativa, por meio de uma pedagogia otimista, politicamente neutra, asséptica, que não misture os aspectos social e educativo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-04-b', 'q-cp-vun-04', 'a escola infantil deve abrir-se ao ambiente (antropológico, social, de valores) porque isto constitui o primeiro livro de leitura da infância, ilustrado com os “sinais-símbolos-códigos” do conhecimento e da fantasia do seu mundo quotidiano.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-04-c', 'q-cp-vun-04', 'a professora, separando as crianças em classes fechadas e isoladas, precisa trabalhar na sua sala de aula e produzir uma experiência educativa que encontre os seus fins em si mesma e no grupo de crianças que atende.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-04-d', 'q-cp-vun-04', 'as creches devem mostrar aversão em relação às propostas experimentais da escolarização infantil, sobretudo em relação a um desenvolvimento científico dos serviços da pré-escola e a uma educação intelectual antecipada.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-04-e', 'q-cp-vun-04', 'a gestão escolar tem que zelar pelo isolamento e pela separação da escola do ambiente social e cultural mais próximo, desenvolvendo mecanismos que regulem a presença da comunidade e de pais e mães no território interno da unidade de ensino.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-05', 'top-ped-18', 'Respeito é um dos temas recorrentes em O cuidado com bebês e crianças pequenas na creche e é um componente importante do currículo que o livro defende, um currículo totalmente inclusivo e centrado em conexões e relações. Nessa obra, a autora Gonzalez-Mena (2014) apresenta os dez princípios baseados na filosofia do respeito, e um deles é:', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Práticas de ensino na educação infantil (PED-XVIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-05-a', 'q-cp-vun-05', 'apresse os bebês e as crianças para que atinjam as metas de aprendizagem e de desenvolvimento preestabelecidas pela unidade de ensino.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-05-b', 'q-cp-vun-05', 'invista tempo e energia para construir aspectos específicos da formação da pessoa, focando apenas no desenvolvimento cognitivo de crianças e bebês.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-05-c', 'q-cp-vun-05', 'finja sentir algo que não sente ou não sentir algo que sente, sempre que necessário, por exemplo: sentir empatia pelas crianças mais indisciplinadas, ainda que não sinta.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-05-d', 'q-cp-vun-05', 'aprenda as formas únicas por meio das quais as crianças se comunicam (choros, palavras, movimentos, gestos, expressões faciais, posições do corpo) e ensine as suas.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-05-e', 'q-cp-vun-05', 'tente salvar as crianças de todos os problemas que surgirem, facilitando o tempo todo o convívio entre elas e tentando protegê-las das situações desagradáveis.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-06', 'top-ped-11', 'Entender o funcionamento do cérebro pode ajudar na compreensão de por que as experiências positivamente reativas são tão importantes no desenvolvimento primário do bebê. Com relação ao pensamento atual sobre o funcionamento do cérebro, conforme Gonzalez-Mena (2014), é correto afirmar que', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Aprendizagem e desenvolvimento na educação infantil e anos iniciais (PED-XI)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-06-a', 'q-cp-vun-06', 'o desenvolvimento do cérebro é linear, ou seja, a capacidade do cérebro de aprender e mudar cresce em um ritmo constante à medida que a criança cresce.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-06-b', 'q-cp-vun-06', 'as experiências antes dos 3 anos de idade têm fator determinante nas estruturas mentais; depois desta etapa, não se pode modificar o cérebro das crianças.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-06-c', 'q-cp-vun-06', 'o cérebro, já na primeira infância, poda, ou elimina seletivamente, os neurônios e as sinapses que não são mais necessários para o desenvolvimento e a aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-06-d', 'q-cp-vun-06', 'as primeiras experiências auxiliam na formação da arquitetura cerebral, o que pode ter impacto tanto no desenvolvimento quanto no aprendizado.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-06-e', 'q-cp-vun-06', 'o modo como o cérebro se desenvolve depende majoritariamente dos genes com os quais se nasce, indicando que o nível de aprendizagem já está predeterminado.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-07', 'top-fgd-04', 'Ao tratar do processo de formação de conceitos, Oliveira (In: La Taille; Oliveira; Dantas, 1992) afirma que a linguagem humana, sistema simbólico fundamental na mediação entre sujeito e objeto de conhecimento, tem, para Vygotsky, duas funções básicas: a de', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Psicologia da educação (FGD-IV)') on conflict (id) do nothing;
