insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-08', 'top-ped-18', 'Ao pensarmos no espaço para as crianças, devemos levar em consideração que o ambiente é composto por gosto, toque, sons e palavras, regras de uso do espaço, luzes e cores, odores, mobílias, equipamentos e ritmos de vida. Nesse sentido, conforme Craidy e Kaercher (2001), é necessário', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Práticas de ensino na educação infantil (PED-XVIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-08-a', 'q-cp-vun-08', 'deixar os espaços educativos todos iguais, evitando, assim, que as crianças fiquem confusas com um ambiente cheio de contrastes.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-08-b', 'q-cp-vun-08', 'fazer da creche e da pré-escola um mundo miniaturizado, de modo que as crianças não estranhem os locais de aprendizagem quando comparados ao mundo real.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-08-c', 'q-cp-vun-08', 'organizar um espaço em que as crianças de diferentes idades, desde os bebês, possam conviver em determinados locais e momentos.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-08-d', 'q-cp-vun-08', 'ter um espaço completamente pronto e praticamente imutável desde o primeiro encontro com as crianças, criando uma sensação de acolhimento e segurança.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-08-e', 'q-cp-vun-08', 'manter, por meio das cores, a separação entre ambientes para meninos e para meninas, utilizando, por exemplo, o azul para eles e o rosa para elas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-09', 'top-ped-19', 'A avaliação pode ser realizada em diferentes momentos e pode ter diversas finalidades. Por exemplo, conforme Bassedas (1999), a avaliação formativa', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Políticas e práticas de avaliação (PED-XIX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-09-a', 'q-cp-vun-09', 'tem a finalidade de abordar informações sobre o saber ou não saber dos alunos em um determinado momento concreto.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-09-b', 'q-cp-vun-09', 'ocorre especificamente no final do processo de ensino-aprendizagem, tanto se este for mais longo como se for mais curto.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-09-c', 'q-cp-vun-09', 'permite realizar uma valorização dos conhecimentos adquiridos pelos alunos, isto é, emitir um juízo de valor.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-09-d', 'q-cp-vun-09', 'possui uma função reguladora e de controle sobre os alunos, pois serve para replanejar o processo de ensino que foi realizado.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-09-e', 'q-cp-vun-09', 'realiza-se de uma maneira contínua ao longo de diferentes atividades e situações que são propostas na sala de aula.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-10', 'top-fgd-15', 'Os registros, além de cumprirem um importante papel na formação dos professores, são parte do processo cuidadoso e contínuo de documentação da história dos processos de aprendizagem das crianças. Nesse sentido, ao discutirem o portfólio de projeto, Oliveira et alii (2015) afirmam que o registro de um projeto é similar ao registro das atividades, mas guarda a principal diferença que é a', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Planejamento e avaliação do ensino e da aprendizagem (FGD-XV)') on conflict (id) do nothing;
