insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-11', 'top-fgd-07', 'Conforme Barbosa (2008), a organização do trabalho pedagógico por meio de projetos precisa', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Teorias e práticas de currículo (FGD-VII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-11-a', 'q-cp-vun-11', 'partir de uma situação, de um problema real, de uma interrogação, de uma questão que afete ao grupo tanto do ponto de vista socioemocional quanto cognitivo.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-11-b', 'q-cp-vun-11', 'projetar a sala de aula com lugares e materiais definidos, prévia e centralmente, pelos adultos, regulando, assim, a interação das crianças com o meio.', false, null) on conflict (id) do nothing;
