insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-11-d', 'q-cp-vun-11', 'tratar o conteúdo por disciplinas, assegurando que cada professor apresente aos demais os avanços dos alunos em sua área específica.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-11-e', 'q-cp-vun-11', 'estabelecer uma ordem linear a ser seguida no desenvolvimento do projeto, podendo ser uma ordem de causa e efeito, de antes e depois, do simples ao complexo etc.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-12', 'top-fgd-24', 'No cotidiano escolar, a educação antirracista visa à erradicação do preconceito, das discriminações e de tratamentos diferenciados.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-12-a', 'q-cp-vun-12', 'Exige, no espaço de convivência das crianças e nas praças públicas, a colocação de cartazes, fotos e livros infantis que expressem a existência de crianças não brancas na sociedade brasileira.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-12-b', 'q-cp-vun-12', 'Incentiva os professores a basearem-se na cor da pele e/ou nas características raciais de seus alunos para diferenciá-los em sala de aula.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-12-c', 'q-cp-vun-12', 'Ensina às crianças e aos adolescentes uma história crítica sobre os diferentes grupos que constituem a história brasileira.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-12-d', 'q-cp-vun-12', 'Reconhece que os educadores, por enfatizarem a história dos europeus, tornaram-se os principais disseminadores e promotores do racismo na sociedade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-12-e', 'q-cp-vun-12', 'Nega a afirmação de que, no ambiente escolar, existe algum tipo de reprodução do racismo existente nas relações sociais extraescolares.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-13', 'top-ped-05', 'A professora Roselinda, em uma escola pública de Educação Infantil, constatou que um de seus alunos já estava aprendendo a escrever. Analisando atentamente o caso, ela descobriu que esse menino recebia bastante estímulo para ler e escrever em casa e resolveu estudar em que nível de aquisição da escrita ele estava. A professora pediu ao menino que escrevesse a palavra “gato”, e ele escreveu “AO”; pediu que escrevesse a palavra “panela”, e ele escreveu “AEA”; pediu que escrevesse a palavra “boneca”, e ele escreveu “OEA”.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-13-a', 'q-cp-vun-13', 'alfabética.', false, null) on conflict (id) do nothing;
