insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-15', 'top-fgd-06', 'Na perspectiva da Didática da Matemática, conforme Moreno (In: Panizza et alii, 2006), pode-se afirmar corretamente que', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Didática e metodologias de ensino (FGD-VI)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-15-a', 'q-cp-vun-15', 'o trabalho do professor consiste em propor ao aluno situações de aprendizagem para que este produza seus conhecimentos partindo da busca pessoal dos procedimentos que lhe permitirão encontrar a resposta para o problema apresentado.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-15-b', 'q-cp-vun-15', 'a aprendizagem ocorre quando, sendo apresentados em sala de aula os estímulos necessários, os alunos conseguem dar as respostas esperadas pelo professor; e a progressão consiste em ir do simples ao complexo, passo a passo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-15-c', 'q-cp-vun-15', 'o aluno, considerado um sujeito carente de saber, aprende por meio do treinamento, isto é, da repetição e da memorização das noções matemáticas, em um processo cumulativo, de somatória de pequenas porções de saber.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-15-d', 'q-cp-vun-15', 'a aula consiste em ensinar as noções matemáticas aos alunos para que, depois, eles consigam aplicá-las; ou seja, eles resolvem problemas se, previamente, o professor lhes ensina os procedimentos consagrados, como fazer contas etc.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-15-e', 'q-cp-vun-15', 'o ensino dos conteúdos matemáticos, na educação infantil, visa preparar as crianças para o ingresso no ensino fundamental; por esse motivo, considera-se que o aluno aprendeu quando já consegue escrever convencionalmente os números.', false, null) on conflict (id) do nothing;
