insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-17', 'top-fgd-12', 'As práticas da inclusão giram em torno de uma questão de fundo: a produção da identidade e da diferença. Conforme Mantoan (2013), diferenciar para incluir é possível, quando', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Educação especial e inclusiva (FGD-XII)') on conflict (id) do nothing;
