insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-18', 'top-ped-07', 'Conforme o Documento Curricular da Rede Municipal de Ensino de Santo André (Volume II), a Instituição de Educação Infantil compreende um espaço de atendimento às crianças de 0 a 5 anos, tendo como objetivo principal', 'facil', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Políticas de educação infantil (PED-VII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-18-a', 'q-cp-vun-18', 'a sua formação como cidadãos.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-18-b', 'q-cp-vun-18', 'o seu desenvolvimento cognitivo.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-18-c', 'q-cp-vun-18', 'a sua segurança física e psicológica.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-18-d', 'q-cp-vun-18', 'a sua preparação para o ensino fundamental.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-18-e', 'q-cp-vun-18', 'a sua alfabetização em Língua Portuguesa e Matemática.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-19', 'top-fgd-14', 'Conforme a Lei Municipal nº 6.833/91, artigo 40, é um direito do integrante do Quadro do Magistério do Município de Santo André, entre outros:', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Identidade e especificidades do trabalho docente (FGD-XIV)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-19-a', 'q-cp-vun-19', 'receber auxílio para a publicação de trabalho e livros didáticos ou técnico-científicos, sempre que fizer solicitação prévia à Administração.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-19-b', 'q-cp-vun-19', 'ter assegurada a oportunidade de frequentar cursos de formação, atualização e especialização profissional, quando desejar, sem a necessidade de recorrer à Administração.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-19-c', 'q-cp-vun-19', 'desfrutar de recesso escolar anual de, no mínimo, 30 (trinta) dias corridos.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-19-d', 'q-cp-vun-19', 'dispor, no ambiente de trabalho, de instalações e material técnico-pedagógico suficientes e adequados, para que possa exercer com eficiência e eficácia suas funções.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-19-e', 'q-cp-vun-19', 'receber, através dos serviços especializados de educação, assistência financeira para exercício profissional ou tratamento de saúde.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-vun-20', 'top-fgd-08', 'Conforme a Lei nº 9.394/1996, art. 4º, o dever do Estado com educação escolar pública será efetivado mediante a garantia de, entre outros:', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://www.vunesp.com.br', 'Concurso público — Prefeitura de Santo André (VUNESP, 2023), cargo Professor de Educação Infantil e Ensino Fundamental — Políticas públicas, organização, financiamento e avaliação da educação (FGD-VIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-20-a', 'q-cp-vun-20', 'atendimento educacional especializado gratuito aos educandos com deficiência, transtornos globais do desenvolvimento e altas habilidades ou superdotação, em todas as etapas, preferencialmente em Centros de Atendimento Especializado (CAEs).', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-20-b', 'q-cp-vun-20', 'oferta de educação escolar regular para jovens e adultos, com características e modalidades adequadas às suas necessidades e disponibilidades, garantindo-se aos que forem trabalhadores as condições de acesso e permanência na escola.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-20-c', 'q-cp-vun-20', 'atendimento ao educando, em todas as etapas da educação básica, exceto para o ensino médio, por meio de programas suplementares de material didático-escolar, transporte, alimentação e assistência à saúde.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-20-d', 'q-cp-vun-20', 'vaga na escola pública de educação infantil, de ensino fundamental e de ensino médio mais próxima da residência para todos os estudantes, a partir do dia em que a criança completar 3 (três) anos de idade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-vun-20-e', 'q-cp-vun-20', 'educação digital, com a garantia de conectividade em alta velocidade em centros de informática em um raio menor que 3 quilômetros da escola, assegurando o desenvolvimento de competências do letramento digital.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-soc-01', 'top-fgd-03', 'Para alguns, a cultura escolar é idêntica à cultura da família, enquanto, para outros, representa uma aculturação. Essa é uma afirmação que encontramos no texto "Os Herdeiros", de Pierre Bourdieu e Jean-Claude Passeron.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-01-a', 'q-cp-soc-01', 'Os estudantes mais favorecidos devem ao meio de origem os hábitos, o treino e as atitudes que lhes são mais úteis nas tarefas escolares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-01-b', 'q-cp-soc-01', 'A escola transforma as desigualdades sociais em igualdades escolares.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-01-c', 'q-cp-soc-01', 'O sistema educativo contribui, com sua própria lógica, para assegurar a perpetuação dos privilégios.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-01-d', 'q-cp-soc-01', 'O valor de um saber-fazer não existe sem o seu uso produtivo, o qual está ausente da escola.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-01-e', 'q-cp-soc-01', 'Nas práticas escolares os problemas são fictícios e têm em vista a avaliação. Esta separação material das práticas escolares e das práticas produtivas é efeito da divisão entre trabalho manual e trabalho intelectual.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-soc-02', 'top-fgd-03', 'Segundo Bourdieu e Passeron (1992), o "capital cultural incorporado" é fruto de um processo educativo, desenvolvido na família e na escola, em um trabalho de assimilação, conquistado à custa de muito investimento, tempo, dinheiro e desembaraço pelos grupos privilegiados de uma sociedade hierarquizada.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-02-a', 'q-cp-soc-02', 'Capital Político, formado por posições políticas assumidas publicamente.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-02-b', 'q-cp-soc-02', 'Capital Simbólico, que se constitui por meio de prestígio, status e/ou honra.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-02-c', 'q-cp-soc-02', 'Capital Material, relacionado à renda, salários e imóveis.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-02-d', 'q-cp-soc-02', 'Capital Social, definido por relações sociais que podem ser capitalizadas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-02-e', 'q-cp-soc-02', 'Capital Cultural, ligado à escolarização, saberes e conhecimentos reconhecidos por diplomas e títulos.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-soc-03', 'top-fgd-03', 'Usou ideias teóricas e métodos objetivos e científicos para desenvolver os fundamentos da sociologia da educação. Este autor viu o ensino como uma tentativa das gerações adultas de influenciar aqueles que ainda não têm experiência em se desenvolver no mundo social. Portanto, a educação, longe de ser uma simples transmissão neutra de conhecimento, é um meio de perpetuar a própria existência da sociedade.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-03-a', 'q-cp-soc-03', 'Karl Marx.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-03-b', 'q-cp-soc-03', 'Émile Durkheim.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-03-c', 'q-cp-soc-03', 'Pierre Bourdieu.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-03-d', 'q-cp-soc-03', 'Basil Bernstein.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-soc-04', 'top-fgd-03', '"O movimento pela Escola Nova fez a crítica dos métodos tradicionais da educação. O marxismo e o positivismo, a seu modo, também fizeram a crítica à educação enquanto pensamento autoritário. Os existencialistas e fenomenologistas, sob o impacto de duas guerras mundiais, perguntavam o que estava errado na educação para formar homens que chegavam a se odiar tanto. O otimismo pedagógico do começo do século não resistiu a tanta violência." (GADOTTI, 1997)
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-04-a', 'q-cp-soc-04', 'Entre os principais representantes do pensamento pedagógico crítico estão Louis Althusser e Pierre Bourdieu.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-04-b', 'q-cp-soc-04', 'Louis Althusser formulou a teoria da escola enquanto aparelho ideológico do Estado.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-04-c', 'q-cp-soc-04', 'A crítica radical à educação oriunda do pensamento pedagógico crítico não substituiu o otimismo com a educação.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-04-d', 'q-cp-soc-04', 'Pierre Bourdieu, junto de Jean Claude Passeron, formulou a teoria da escola enquanto violência simbólica.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-soc-04-e', 'q-cp-soc-04', 'As teorias derivadas do pensamento pedagógico crítico são, frequentemente, chamadas de crítico-reprodutivistas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-pes-01', 'top-fgd-09', 'Em relação ao papel do professor-pesquisador, assinale a afirmativa incorreta.', 'dificil', 'CONCURSO_PUBLICO_OFICIAL', 2024, 'https://arquivos.qconcursos.com/prova/arquivo_prova/106008/instituto-access-2024-ufape-pedagogo-prova.pdf', 'Concurso público — UFAPE (Instituto Access, 2024), cargo Pedagogo — Metodologia de pesquisa em educação (FGD-IX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-01-a', 'q-cp-pes-01', 'Ação-pesquisa-ação e pesquisa-ação são nomenclaturas que se referem ao mesmo conceito, cujo significado pode ser assim enunciado: a busca de formas de ações coletivas que objetivam a resolução de algum problema ou a transformação de uma dada realidade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-01-b', 'q-cp-pes-01', 'A palavra ação, na expressão pesquisa-ação, serve para destacar o fato de que a ação dos professores na educação básica trouxe à tona a necessidade de se produzir conhecimento para esse nível de ensino.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-01-c', 'q-cp-pes-01', 'Houve, a priori, um projeto de pesquisa-ação que gerou os movimentos considerados pesquisa-ação.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-01-d', 'q-cp-pes-01', 'Tanto na Inglaterra quanto no Brasil, houve uma conjuntura oriunda dos professores dos ensino básico atentos às demandas de seus alunos que, no caso da Inglaterra, motivou o conceito de professor pesquisador e cedeu as categorias conceituais da pesquisa-ação quando esses professores foram estimulados a colaborar com os especialistas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-01-e', 'q-cp-pes-01', 'No Brasil considerou-se que o movimento de professores apresentava características que se assemelhavam à metodologia da pesquisa-ação.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-pes-02', 'top-fgd-09', 'Segundo Goldenberg (2011), a pesquisa não é controlável. Trata-se de um processo no qual é impossível prever as etapas. Ao pesquisar, o pesquisador está em estado de tensão, pois reconhece a parcialidade e a limitação do seu conhecimento. Ao produzir o projeto, desenha os caminhos a serem seguidos no desenvolvimento do trabalho de pesquisa, explicitando as etapas a serem alcançadas, os instrumentos e as estratégias que poderão ser usados.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-02-a', 'q-cp-pes-02', 'apresenta argumentos acerca da relevância da questão, levando em consideração os estudos anteriores sobre o tema, para assinalar suas eventuais limitações e destacar, assim, a necessidade de continuar a pesquisá-lo, e as contribuições, a relevância social e científica da questão de estudo', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-02-b', 'q-cp-pes-02', 'destaca, expõe e discute os referenciais teóricos, ou seja, os instrumentos conceituais em que o projeto se apoia para conduzir o raciocínio, a explicação dos aspectos do real que se propôs a estudar, imprescindível para qualquer tipo de pesquisa, devendo ainda o aspecto do real ser consistente e atual', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-02-c', 'q-cp-pes-02', 'é uma questão que descreve uma necessidade de estudo. Precisa ser clara, para que o leitor entenda a importância da questão. Pode ser originária de muitas fontes potenciais. Pode provir de uma experiência que os pesquisadores tiveram em suas vidas pessoais ou em seus locais de trabalho', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-02-d', 'q-cp-pes-02', 'indica o que se pretende conhecer, medir ou provar no decorrer da pesquisa, ou seja, as metas que se deseja alcançar. Discrimina a intenção de todo o estudo de pesquisa e, por isso, deve ser apresentada de maneira clara e específica', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-pes-03', 'top-fgd-09', 'Segundo Minayo (2010, p. 26), o ciclo da pesquisa qualitativa é dividido em três etapas. Uma delas "consiste em levar para a prática empírica a construção teórica elaborada na primeira etapa. Essa etapa combina instrumentos de observação, entrevistas ou outras modalidades de comunicação e interlocução com os pesquisadores, levantamento de material documental e outros".
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-03-a', 'q-cp-pes-03', 'divulgação dos resultados', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-03-b', 'q-cp-pes-03', 'exploratória da pesquisa', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-03-c', 'q-cp-pes-03', 'tratamento do material', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-03-d', 'q-cp-pes-03', 'trabalho de campo', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-pes-04', 'top-fgd-09', 'Conforme afirma Vasconcellos (2009), a tarefa do professor é extremamente importante e complexa, o que exige que ele esteja constantemente qualificado. O professor deve estar preparado para exercer a sua prática, considerando que ela é dinâmica e aberta, e não uma atividade mecânica e repetitiva.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-04-a', 'q-cp-pes-04', 'a troca entre os docentes mais experientes com os professores em início de carreira não seja considerada importante, pois as ideias pedagógicas precisam ser superadas', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-04-b', 'q-cp-pes-04', 'o professor seja também pesquisador e que a escola não seja vista apenas como um local de trabalho, mas, ao mesmo tempo, como espaço de formação', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-04-c', 'q-cp-pes-04', 'a reunião pedagógica seja um espaço que pode ser substituído por cursos formativos, com temáticas que sejam pensadas por cada professor', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-pes-04-d', 'q-cp-pes-04', 'a qualificação do professor seja algo a priori, já que, ao sair de cursos bem avaliados, o docente não necessitará se manter em formação', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-ant-01', 'top-ped-01', 'Tendo por base um referencial histórico e cultural, defende-se certo deslocamento do conhecimento escolar, como perspectiva científica e universalizante, para dar centralidade a outros tipos de saberes, entre eles os comunitários, os do cotidiano, os da arte e das demais formas de linguagem e multiculturalidade.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-01-a', 'q-cp-ant-01', 'os conhecimentos reconhecidos socialmente precisam ser enquadrados nas respectivas disciplinas escolares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-01-b', 'q-cp-ant-01', 'parte do conhecimento deve servir à visão de mundo hegemônica, por isso é importante que conste nos currículos escolares.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-01-c', 'q-cp-ant-01', 'a diversidade é elemento constitutivo do processo de ensino e de aprendizagem.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-01-d', 'q-cp-ant-01', 'a mutabilidade do conhecimento tem pouca relevância no processo de ensino e aprendizagem.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-01-e', 'q-cp-ant-01', 'a neutralidade curricular permite o desenvolvimento da intencionalidade educacional, por isso é requerida.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-ant-02', 'top-ped-01', 'Assinale a opção correta a respeito dos estudos a respeito de currículo.', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2023, 'https://cdn.cebraspe.org.br/concursos/pref_camacari_ba_23/arquivos/891_PREF_CAMACARI_002_01.PDF', 'Concurso público — Prefeitura de Camaçari-BA (CEBRASPE, 2023), cargo Coordenador Pedagógico — Antropologia da educação (PED-I)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-02-a', 'q-cp-ant-02', 'Bobbitt desenvolveu uma perspectiva pós-crítica de currículo, enfocando a importância da identidade, da alteridade e da subjetividade.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-02-b', 'q-cp-ant-02', 'Na teoria pós-crítica, a discussão sobre o currículo enfoca a preocupação com a cultura e os elementos de gênero, raça, etnia e sexualidade.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-02-c', 'q-cp-ant-02', 'De acordo com o enfoque multiculturalista de currículo, a igualdade pode ser obtida a partir de um currículo hegemônico.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-02-d', 'q-cp-ant-02', 'As teorias pós-críticas do currículo, ao aceitarem os conhecimentos e os saberes dominantes, acabam por se concentrar em questões técnicas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-02-e', 'q-cp-ant-02', 'Para a perspectiva tradicional, o currículo oculto ensina o conformismo e o individualismo.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-ant-03', 'top-ped-01', 'Em 2004, o Ministério da Educação divulgou as Diretrizes Curriculares Nacionais para a Educação das Relações Étnico-Raciais e para o Ensino de História e Cultura Afro-Brasileira e Africana. Em 2006, foi lançada a publicação Orientações e Ações para a Educação das Relações Étnico-Raciais, em que são sugeridas algumas atividades a ser desenvolvidas.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-03-a', 'q-cp-ant-03', 'Recomenda-se a utilização de músicas e canções populares, literatura e poesias, com prioridade para aquelas que enaltecem a cultura negra, indígena e regional como, por exemplo, Kizomba, Menina Bonita do Laço de Fita, Os Escravos de Jô e As Borboletas, de Vinícius de Morais, tendo-se o cuidado de manter a originalidade da letra.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-03-b', 'q-cp-ant-03', 'É importante que a temática das relações étnico-raciais esteja contida nos projetos pedagógicos das instituições, com práticas localizadas em determinadas fases do ano para que não seja esquecida.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-03-c', 'q-cp-ant-03', 'Para ampliar a diversidade cultural presente nos currículos, as atividades devem mudar o foco etnocêntrico marcadamente de raiz europeia.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-03-d', 'q-cp-ant-03', 'O ensino de história e cultura africana se fará por diferentes meios, incluindo projetos; para tanto, os estabelecimentos de educação básica, em todos os níveis, precisam providenciar o registro da história não contada dos negros brasileiros.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-03-e', 'q-cp-ant-03', 'No ensino médio, sugere-se apresentar mais cartuns, quadrinhos, vídeos e revistas e apresentar com cuidado os autores clássicos, uma vez que, em muitos, há conotação discriminatória da questão racial.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-ant-04', 'top-ped-01', 'A educação da cultura visual pode ser aliada de métodos de ensino e dinâmicas didáticas que ampliam a experiência estética, produzindo outras formas de significação. Além de contextualizar e integrar saberes populares, diferentes formas de mídia e estilos culturais, ela possibilita que identidades sociais sejam valorizadas em suas múltiplas referências.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-04-a', 'q-cp-ant-04', 'As identidades sociais não são discursos significativos na produção simbólica da cultura popular.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-04-b', 'q-cp-ant-04', 'A história da arte é uma das narrativas possíveis para o ensino das artes, mas há outras, advindas das diferentes formas tradicionais de saberes e fazeres.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-04-c', 'q-cp-ant-04', 'As mídias sociais não representam formas simbólicas passíveis de análise estética ou elaboração didática.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-04-d', 'q-cp-ant-04', 'A cultura popular só pode ser introduzida em contextos escolares caso seja usada como um exemplo de mau uso de técnicas e materiais.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-ant-04-e', 'q-cp-ant-04', 'A liberdade de expressão e a experimentação artística são estruturas incompatíveis com os conteúdos curriculares.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-nes-01', 'top-ped-10', 'A Educação tem sido cada vez mais considerada uma área-chave para enfrentar os problemas sociais da humanidade. Diante disso, o conceito de Educação tem sido ampliado e adjetivado: já não se restringe mais ao processo de ensino-aprendizagem no interior de unidades escolares formais e pode ser categorizado em educação formal, não formal e informal.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-01-a', 'q-cp-nes-01', 'tem como método básico a vivência e a reprodução do conhecido, a reprodução da experiência segundo os modos e as formas como foi apreendida e codificada;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-01-b', 'q-cp-nes-01', 'os resultados acontecem a partir do desenvolvimento do senso comum nos indivíduos, senso este que orienta suas formas de pensar e agir espontaneamente;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-01-c', 'q-cp-nes-01', 'socializa os indivíduos, desenvolve hábitos, atitudes, comportamentos, modos de pensar e de se expressar no uso da linguagem, segundo valores e crenças de grupos que frequentam ou a que pertençam por herança, desde o nascimento;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-01-d', 'q-cp-nes-01', 'tem foco na aprendizagem de conteúdos historicamente sistematizados, normalizados por leis, dentre os quais destacam-se o de formar o indivíduo como um cidadão ativo, desenvolver habilidades e competências várias, fortalecer a criatividade, a percepção e a motricidade;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-01-e', 'q-cp-nes-01', 'possui metodologias concebidas a partir da problematização da vida cotidiana; os conteúdos emergem com base nos temas que se colocam como necessidades, carências, desafios, obstáculos ou ações empreendedoras a serem realizadas, e não são dados a priori, mas geralmente construídos no processo.', true, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-nes-02', 'top-ped-10', 'A pedagogia social é um componente da Pedagogia que se responsabiliza diretamente pela inclusão das crianças e jovens, em situação de vulnerabilidade social, no universo não escolar. Quanto mais a população de um país é entregue à própria sorte, maior se faz a necessidade de um fazer pedagógico voltado para a realidade das crianças e adolescentes expostos a todo o tipo de dificuldades oriundas de uma educação direcionada para um público com valores e necessidades bem diferentes.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-02-a', 'q-cp-nes-02', 'do passado;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-02-b', 'q-cp-nes-02', 'da inclusão;', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-02-c', 'q-cp-nes-02', 'tradicional;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-02-d', 'q-cp-nes-02', 'experimental;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-02-e', 'q-cp-nes-02', 'consensual.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-nes-03', 'top-ped-10', 'É objetivo dos espaços socioeducativos no que se refere aos jovens em situação de conflito com a lei:', 'media', 'CONCURSO_PUBLICO_OFICIAL', 2018, 'https://arquivos.qconcursos.com/prova/arquivo_prova/62261/fgv-2018-prefeitura-de-niteroi-rj-pedagogo-prova.pdf', 'Concurso público — Prefeitura de Niterói-RJ / SASDH (FGV, 2018), cargo Pedagogo — Atuação de pedagogos em espaços não escolares (PED-X)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-03-a', 'q-cp-nes-03', 'apresentar novas formas de convivência;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-03-b', 'q-cp-nes-03', 'o acolhimento por uma equipe psicossocial;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-03-c', 'q-cp-nes-03', 'reeducar, visando à cidadania;', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-03-d', 'q-cp-nes-03', 'trabalhar, juntamente com as famílias, para sua recuperação;', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-03-e', 'q-cp-nes-03', 'oferecer educação continuada com vistas à profissionalização.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-nes-04', 'top-ped-10', 'No campo dos sistemas de saúde, os debates acerca da educação e desenvolvimento dos recursos humanos levaram a contrastar os paradigmas das denominadas Educação Continuada e Educação Permanente (PNEPS, 2006, p. 44). Sendo assim, relacione os tipos de educação representados pelas letras A e B com as características elencadas logo abaixo.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-04-a', 'q-cp-nes-04', 'I-A, II-B, III-A, IV-B', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-04-b', 'q-cp-nes-04', 'I-B, II-B, III-A, IV-A', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-04-c', 'q-cp-nes-04', 'I-A, II-A, III-B, IV-B', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-04-d', 'q-cp-nes-04', 'I-B, II-A, III-B, IV-B', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-nes-04-e', 'q-cp-nes-04', 'I-B, II-A, III-B, IV-A', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-cam-01', 'top-ped-15', 'Instituídas pela Resolução CNE/CEB nº 1/2002, as Diretrizes Operacionais para a Educação Básica nas Escolas do Campo são fundamentais para a estruturação do ensino rural. Sua aplicação deve ser articulada à Resolução CNE/CEB nº 2/2008, que atualiza as diretrizes nacionais e reforça os princípios de identidade e territorialidade das populações camponesas. Com base nesse conjunto normativo, analise as assertivas abaixo e assinale V, se verdadeiras, ou F, se falsas.
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-01-a', 'q-cp-cam-01', 'F – V – V – F – V.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-01-b', 'q-cp-cam-01', 'V – V – F – F – V.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-01-c', 'q-cp-cam-01', 'F – V – F – V – V.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-01-d', 'q-cp-cam-01', 'V – F – V – F – F.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-01-e', 'q-cp-cam-01', 'V – F – V – V – F.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-cam-02', 'top-ped-15', '"A Educação do Campo, tratada como educação rural na legislação brasileira, incorpora os espaços da floresta, da pecuária, das minas e da agricultura, e se estende, também, aos espaços pesqueiros, caiçaras, ribeirinhos, quilombolas e extrativistas, entre outros." (Resolução SEE/MG nº 2.197/2012)
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-02-a', 'q-cp-cam-02', 'I e II são proposições falsas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-02-b', 'q-cp-cam-02', 'I e II são proposições verdadeiras, e II é uma justificativa correta de I.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-02-c', 'q-cp-cam-02', 'I e II são proposições verdadeiras, mas II não é uma justificativa correta de I.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-02-d', 'q-cp-cam-02', 'I é uma proposição falsa, e II é uma proposição verdadeira.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-02-e', 'q-cp-cam-02', 'I é uma proposição verdadeira, e II é uma proposição falsa.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-cam-03', 'top-ped-15', 'Analise as informações a seguir:
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-03-a', 'q-cp-cam-03', 'As duas afirmativas são verdadeiras.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-03-b', 'q-cp-cam-03', 'A afirmativa I é verdadeira, e a II é falsa.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-03-c', 'q-cp-cam-03', 'A afirmativa II é verdadeira, e a I é falsa.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-03-d', 'q-cp-cam-03', 'As duas afirmativas são falsas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-cp-cam-04', 'top-ped-15', 'O Decreto nº 7.352, de 4 de novembro de 2010, dispõe sobre a política de educação do campo e o Programa Nacional de Educação na Reforma Agrária - PRONERA. O artigo 1º reza: "A política de educação do campo destina-se à ampliação e qualificação da oferta de educação básica e superior às populações do campo, e será desenvolvida pela União em regime de colaboração com os Estados, o Distrito Federal e os Municípios, de acordo com as diretrizes e metas estabelecidas no Plano Nacional de Educação e o disposto neste Decreto."
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-04-a', 'q-cp-cam-04', 'I, II e III.', true, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-04-b', 'q-cp-cam-04', 'I e II, apenas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-04-c', 'q-cp-cam-04', 'II e III, apenas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-cp-cam-04-d', 'q-cp-cam-04', 'I e III, apenas.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-001', 'top-ped-05', 'Uma professora do 1º ano do Ensino Fundamental percebe que parte da turma já domina a relação grafema-fonema, mas ainda não consegue empregar a escrita em situações sociais de uso, como escrever um bilhete com finalidade real. Considerando a distinção entre alfabetização e letramento, a intervenção mais adequada é:', 'media', 'IA_INEDITA', null, null, 'Componente específico de Pedagogia — Alfabetização e letramento (PED-V)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-001-a', 'q-001', 'Intensificar exercícios de repetição silábica até a automatização completa antes de qualquer atividade de escrita espontânea.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-001-b', 'q-001', 'Propor situações reais de uso da escrita (bilhetes, listas, convites) articuladas ao trabalho sistemático com o sistema de escrita alfabética.', true, 'Alfabetizar letrando: o domínio do sistema alfabético deve caminhar junto com práticas sociais de leitura e escrita, e não em etapas estanques.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-001-c', 'q-001', 'Suspender o ensino sistemático do sistema alfabético até que o letramento esteja consolidado.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-001-d', 'q-001', 'Focar exclusivamente em atividades de consciência fonológica oral, sem produção escrita.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-001-e', 'q-001', 'Avaliar a turma apenas por ditado, já que é o instrumento mais direto para medir a alfabetização.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-002', 'top-ped-05', 'Sobre a psicogênese da língua escrita (Emilia Ferreiro e Ana Teberosky), a hipótese silábico-alfabética caracteriza-se por:', 'media', 'IA_INEDITA', null, null, 'Componente específico de Pedagogia — Alfabetização e letramento (PED-V)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-002-a', 'q-002', 'A criança atribui uma letra para cada sílaba da palavra, sem relação sonora.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-002-b', 'q-002', 'A criança já compreende que a escrita representa o som da fala, mas ainda oscila entre grafar uma letra por sílaba e mais de uma letra por sílaba.', true, 'É uma fase de transição entre a hipótese silábica e a alfabética, marcada por essa oscilação.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-002-c', 'q-002', 'A criança já escreve convencionalmente, respeitando todas as normas ortográficas.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-002-d', 'q-002', 'A criança não estabelece nenhuma relação entre quantidade de letras e tamanho do objeto nomeado.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-002-e', 'q-002', 'A criança usa exclusivamente letras do próprio nome para grafar qualquer palavra.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-003', 'top-ped-19', 'Ao final de uma sequência didática, um professor aplica uma prova somativa e, com base apenas nessa nota, decide se o aluno avança ou não de conteúdo, sem retomar os erros identificados. Essa prática está mais distante dos princípios de:', 'facil', 'IA_INEDITA', null, null, 'Componente específico de Pedagogia — Políticas e práticas de avaliação (PED-XIX)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-003-a', 'q-003', 'Avaliação classificatória.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-003-b', 'q-003', 'Avaliação formativa, que pressupõe usar os resultados para reorientar o ensino durante o processo.', true, 'A avaliação formativa é processual e serve para ajustar a intervenção pedagógica, não apenas para classificar ao final.') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-003-c', 'q-003', 'Avaliação somativa.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-003-d', 'q-003', 'Avaliação diagnóstica inicial.', false, null) on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-003-e', 'q-003', 'Avaliação em larga escala.', false, null) on conflict (id) do nothing;
insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-004', 'top-ped-19', 'Uma escola pública utiliza o resultado de uma avaliação em larga escala apenas para ranquear turmas e divulgar publicamente o desempenho de cada professor. Do ponto de vista das políticas de avaliação educacional, essa prática:', 'dificil', 'IA_INEDITA', null, null, 'Formação Geral Docente — Políticas públicas, organização, financiamento e avaliação (FGD-VIII)') on conflict (id) do nothing;
insert into public.question_options (id, question_id, text, is_correct, explanation) values ('q-004-a', 'q-004', 'É recomendada, pois estimula a competição entre docentes.', false, null) on conflict (id) do nothing;
