insert into public.questions (id, topic_id, statement, difficulty, origin, origin_year, origin_link, competency_ref) values ('q-005', 'top-ped-08', 'As Diretrizes Curriculares Nacionais para a Educação Infantil concebem a criança como:', 'facil', 'IA_INEDITA', null, null, 'Componente específico de Pedagogia — Criança e infância (PED-VIII)') on conflict (id) do nothing;
